// NIAS CMMS 파이프라인 - 원샷 배치 스크립트 (Node.js 버전)
// PowerShell here-string 인코딩 문제(한글 주석 깨짐)를 피하기 위해 Node.js로 작성.
// 실행: node deploy_cmms_pipeline.cjs

const fs = require('fs');
const path = require('path');

const files = {
  "src/adapters/assetAdapter.ts": "// src/adapters/assetAdapter.ts\n//\n// PURPOSE\n//   Refactoring Plan \u00a71.5 \uad6c\ud604\uccb4.\n//   staging_legacy_assets \ub4f1\uc5d0\uc11c IMPA \ucf54\ub4dc\ub098 KKS \ud0dc\uadf8\uac00 \ube44\uc5b4 \uc788\ub294(NULL/\ube48\ubb38\uc790\uc5f4)\n//   \ub808\ucf54\ub4dc\ub97c \ub9cc\ub098\ub354\ub77c\ub3c4 UI/\ud6c4\uc18d \ud30c\uc774\ud504\ub77c\uc778\uc774 \uc808\ub300 \ud06c\ub798\uc2dc\ud558\uc9c0 \uc54a\ub3c4\ub85d,\n//   \uc548\uc804\ud55c \uae30\ubcf8\uac12([Pending] \ud0dc\uadf8, UNMAPPED-ASSET \ub4f1)\uc73c\ub85c \uc790\ub3d9 \ub300\uccb4\ud558\ub294\n//   \uc77d\uae30 \uc804\uc6a9(read-only) \uc5b4\ub311\ud130.\n//\n// GUARANTEES\n//   - \uc774 \ud30c\uc77c\uc758 \ubaa8\ub4e0 \ud568\uc218\ub294 \uc21c\uc218 \ud568\uc218\ub2e4. DB \uc4f0\uae30, \ub124\ud2b8\uc6cc\ud06c \ud638\ucd9c, \uc0c1\ud0dc \ubcc0\uacbd \uc5c6\uc74c.\n//   - \uc5b4\ub5a4 \uc785\ub825(undefined/null/\ube48\ubb38\uc790\uc5f4/\uacf5\ubc31\ubb38\uc790\uc5f4)\uc774 \ub4e4\uc5b4\uc640\ub3c4 \uc608\uc678\ub97c \ub358\uc9c0\uc9c0 \uc54a\uace0\n//     \ud56d\uc0c1 \uc720\ud6a8\ud55c fallback \uac12\uc744 \ubc18\ud658\ud55c\ub2e4 (Graceful Degradation).\n//   - \"PROMOTED\"(\uc815\uc2dd \uc2b9\uaca9) \ud310\ub2e8\uc740 \uc774 \ud30c\uc77c\uc774 \ub0b4\ub9ac\uc9c0 \uc54a\ub294\ub2e4 \u2014 \uc624\uc9c1 \ud45c\uc2dc/\uc870\ud68c\uc6a9\n//     \uc548\uc804 \ubcc0\ud658\ub9cc \uc218\ud589\ud55c\ub2e4. \uc2e4\uc81c assets \ud14c\uc774\ube14 \uc2b9\uaca9 \uc5ec\ubd80\ub294 staging \ud30c\uc774\ud504\ub77c\uc778\uc758\n//     mapping_status\ub85c \ubcc4\ub3c4 \ud310\ub2e8\ud55c\ub2e4.\n\n// ----------------------------------------------------------------------------\n// 1. \uc0c1\uc218 \u2014 \uacf5\ubc31 \ub370\uc774\ud130 \ub300\uc751 \uae30\ubcf8\uac12\n// ----------------------------------------------------------------------------\n\n/** \ud0dc\uadf8/\ucf54\ub4dc\ub958\uac00 \ube44\uc5b4\uc788\uc744 \ub54c \uc0ac\ub78c\uc774 \uc77d\ub294 \ud654\uba74\uc5d0 \ub178\ucd9c\ud560 \ud50c\ub808\uc774\uc2a4\ud640\ub354 */\nexport const PENDING_LABEL = '[Pending]';\n\n/** equipment_tag \uc790\uccb4\uac00 \ud655\uc815\ub418\uc9c0 \uc54a\uc740 \uc790\uc0b0\uc5d0 \ubd80\uc5ec\ud558\ub294 \uace0\uc815 fallback \uc2dd\ubcc4\uc790 \uc811\ub450\uc0ac */\nexport const UNMAPPED_ASSET_PREFIX = 'UNMAPPED-ASSET';\n\n/** IMPA \ucf54\ub4dc \ubbf8\ubc30\uc815 \uc790\uc7ac\uc5d0 \ubd80\uc5ec\ud558\ub294 fallback */\nexport const UNMAPPED_IMPA_CODE = 'UNMAPPED-IMPA';\n\n/** criticality \ub9e4\ud551 \uc2e4\ud328 \uc2dc \uc548\uc804\uce21 \uae30\ubcf8\uac12 (\uacfc\uc18c\ud3c9\uac00\ub85c \uc778\ud55c \uc815\ube44\ub204\ub77d \ubc29\uc9c0 \uc704\ud574 \uc911\uac04\uac12 \ucc44\ud0dd) */\nexport const DEFAULT_CRITICALITY: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' = 'MEDIUM';\n\nconst CRITICALITY_ALIASES: Record<string, 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW'> = {\n  critical: 'CRITICAL',\n  crit: 'CRITICAL',\n  high: 'HIGH',\n  hi: 'HIGH',\n  medium: 'MEDIUM',\n  med: 'MEDIUM',\n  normal: 'MEDIUM',\n  low: 'LOW',\n};\n\nconst STATUS_ALIASES: Record<string, 'OPERATIONAL' | 'MAINTENANCE' | 'STANDBY' | 'OUT_OF_SERVICE'> = {\n  running: 'OPERATIONAL',\n  operational: 'OPERATIONAL',\n  active: 'OPERATIONAL',\n  maintenance: 'MAINTENANCE',\n  repair: 'MAINTENANCE',\n  standby: 'STANDBY',\n  idle: 'STANDBY',\n  out_of_service: 'OUT_OF_SERVICE',\n  down: 'OUT_OF_SERVICE',\n  offline: 'OUT_OF_SERVICE',\n};\n\n// ----------------------------------------------------------------------------\n// 2. \uc720\ud2f8\n// ----------------------------------------------------------------------------\n\n/** null/undefined/\ube48\ubb38\uc790\uc5f4/\uacf5\ubc31\ub9cc \uc788\ub294 \ubb38\uc790\uc5f4\uc744 \"\ube44\uc5b4\uc788\uc74c\"\uc73c\ub85c \uac04\uc8fc */\nfunction isBlank(value: string | null | undefined): value is null | undefined | '' {\n  return value === null || value === undefined || value.trim().length === 0;\n}\n\n/**\n * \uacb0\uc815\ub860\uc801 fallback \ud0dc\uadf8 \uc0dd\uc131. \uac19\uc740 legacy_tag/legacy_name \uc785\ub825\uc5d0\ub294 \ud56d\uc0c1\n * \uac19\uc740 fallback \uac12\uc744 \ubc18\ud658\ud574\uc57c \ud6c4\uc18d \uc870\uc778(\uc608: asset_tag_alias)\uc5d0\uc11c \uc911\ubcf5\uc774\n * \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubcc4\ub3c4 \uc2dc\ud000\uc2a4/DB \uc5c6\uc774\ub3c4 \uc548\uc804\ud558\ub3c4\ub85d \uac04\ub2e8\ud55c \ubb38\uc790\uc5f4 \ud574\uc2dc\ub97c \uc0ac\uc6a9\ud55c\ub2e4.\n */\nfunction stableSuffix(seed: string): string {\n  let hash = 0;\n  for (let i = 0; i < seed.length; i++) {\n    hash = (hash * 31 + seed.charCodeAt(i)) >>> 0; // unsigned 32bit wrap\n  }\n  return hash.toString(16).toUpperCase().padStart(8, '0');\n}\n\n// ----------------------------------------------------------------------------\n// 3. \ud544\ub4dc\ubcc4 Graceful Fallback Resolver\n// ----------------------------------------------------------------------------\n\n/**\n * equipment_tag \ud655\uc815\uac12\uc774 \uc5c6\uc744 \ub54c \uc0ac\uc6a9\ud560 \uc548\uc815\uc801\uc778 fallback\uc744 \ub9cc\ub4e0\ub2e4.\n * \uc6d0\ubcf8 legacy_tag\uac00 \uc788\uc73c\uba74 \uadf8\uac83\uc744 \uc2dc\ub4dc\ub85c \uc0ac\uc6a9\ud574 \uc7ac\ud604 \uac00\ub2a5\ud55c \uc2dd\ubcc4\uc790\ub97c \ub9cc\ub4e4\uace0,\n * \uadf8\ub9c8\uc800 \uc5c6\uc73c\uba74 legacy_name\uc744 \uc2dc\ub4dc\ub85c \uc4f4\ub2e4.\n */\nexport function resolveEquipmentTag(\n  proposedEquipmentTag: string | null | undefined,\n  legacyTag: string | null | undefined,\n  legacyName: string | null | undefined\n): { value: string; isFallback: boolean } {\n  if (!isBlank(proposedEquipmentTag)) {\n    return { value: proposedEquipmentTag!.trim(), isFallback: false };\n  }\n  const seed = !isBlank(legacyTag) ? legacyTag! : !isBlank(legacyName) ? legacyName! : 'UNKNOWN';\n  return { value: `${UNMAPPED_ASSET_PREFIX}-${stableSuffix(seed)}`, isFallback: true };\n}\n\n/** KKS \ucf54\ub4dc \u2014 \ube44\uc5b4\uc788\uc73c\uba74 [Pending] \ub77c\ubca8 */\nexport function resolveKksCode(proposedKksCode: string | null | undefined): { value: string; isFallback: boolean } {\n  if (!isBlank(proposedKksCode)) return { value: proposedKksCode!.trim(), isFallback: false };\n  return { value: PENDING_LABEL, isFallback: true };\n}\n\n/** ISO 14224 Class \u2014 \ube44\uc5b4\uc788\uc73c\uba74 [Pending] \ub77c\ubca8 (legacy_type_filter\ub85c \ucd5c\uc18c \ucd94\uc815 \uc2dc\ub3c4) */\nexport function resolveIso14224Class(\n  proposedClass: string | null | undefined,\n  legacyTypeFilter?: 'PLANT' | 'INSTRUMENTS' | null\n): { value: string; isFallback: boolean } {\n  if (!isBlank(proposedClass)) return { value: proposedClass!.trim(), isFallback: false };\n  if (legacyTypeFilter === 'INSTRUMENTS') return { value: 'Instrument', isFallback: true };\n  if (legacyTypeFilter === 'PLANT') return { value: PENDING_LABEL, isFallback: true }; // PLANT\ub294 \uc138\ubd80 \ud074\ub798\uc2a4 \ucd94\uc815 \ubd88\uac00\n  return { value: PENDING_LABEL, isFallback: true };\n}\n\n/** IMPA \ucf54\ub4dc \u2014 \ube44\uc5b4\uc788\uc73c\uba74 UNMAPPED-IMPA */\nexport function resolveImpaCode(proposedImpaCode: string | null | undefined): { value: string; isFallback: boolean } {\n  if (!isBlank(proposedImpaCode)) return { value: proposedImpaCode!.trim(), isFallback: false };\n  return { value: UNMAPPED_IMPA_CODE, isFallback: true };\n}\n\n/** Criticality \u2014 \ud45c\uae30 \ud63c\uc7ac(\ub300\uc18c\ubb38\uc790/\uc57d\uc5b4) \uc815\uaddc\ud654, \uc2e4\ud328 \uc2dc DEFAULT_CRITICALITY */\nexport function resolveCriticality(\n  raw: string | null | undefined\n): { value: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW'; isFallback: boolean } {\n  if (isBlank(raw)) return { value: DEFAULT_CRITICALITY, isFallback: true };\n  const normalized = CRITICALITY_ALIASES[raw!.trim().toLowerCase()];\n  if (normalized) return { value: normalized, isFallback: false };\n  return { value: DEFAULT_CRITICALITY, isFallback: true };\n}\n\n/** Status \u2014 \ud45c\uae30 \ud63c\uc7ac \uc815\uaddc\ud654, \uc2e4\ud328 \uc2dc OUT_OF_SERVICE\ub85c \ubcf4\uc218\uc801 fallback\n *  (\uc6b4\uc601\uc911 \uc790\uc0b0\uc744 \uc798\ubabb \ud45c\uc2dc\ud558\ub294 \uac83\ubcf4\ub2e4, \ubbf8\ud655\uc778 \uc790\uc0b0\uc744 \uc815\uc9c0\ub85c \ubcf4\uc774\uac8c \ud558\ub294 \ud3b8\uc774 \ub354 \uc548\uc804) */\nexport function resolveStatus(\n  raw: string | null | undefined\n): { value: 'OPERATIONAL' | 'MAINTENANCE' | 'STANDBY' | 'OUT_OF_SERVICE'; isFallback: boolean } {\n  if (isBlank(raw)) return { value: 'OUT_OF_SERVICE', isFallback: true };\n  const normalized = STATUS_ALIASES[raw!.trim().toLowerCase()];\n  if (normalized) return { value: normalized, isFallback: false };\n  return { value: 'OUT_OF_SERVICE', isFallback: true };\n}\n\n// ----------------------------------------------------------------------------\n// 4. \ub808\ucf54\ub4dc \ub2e8\uc704 \ud1b5\ud569 \uc5b4\ub311\ud130\n// ----------------------------------------------------------------------------\n\n/** staging_legacy_assets 1\ud589\uc5d0 \ub300\uc751\ud558\ub294 \ucd5c\uc18c \uc785\ub825 shape (\uc77d\uae30 \uc804\uc6a9 \uc785\ub825) */\nexport interface StagingAssetRowInput {\n  legacyTag?: string | null;\n  legacyName?: string | null;\n  legacyLocationRaw?: string | null;\n  legacyMaker?: string | null;\n  legacyCriticalityRaw?: string | null;\n  legacyStatusRaw?: string | null;\n  legacyTypeFilter?: 'PLANT' | 'INSTRUMENTS' | null;\n  legacyImpaCodeRaw?: string | null;\n  proposedEquipmentTag?: string | null;\n  proposedKksCode?: string | null;\n  proposedIso14224Class?: string | null;\n  proposedImpaCode?: string | null;\n  proposedCriticality?: string | null;\n}\n\n/** UI/\ub2e4\uc6b4\uc2a4\ud2b8\ub9bc \uc18c\ube44\uc6a9, \ud56d\uc0c1 \uc644\uc804\ud788 \ucc44\uc6cc\uc9c4(fallback \ud3ec\ud568) \uc548\uc804 \ubdf0 */\nexport interface SafeAssetView {\n  equipmentTag: string;\n  assetName: string;\n  locationArea: string;\n  manufacturer: string;\n  kksCode: string;\n  iso14224Class: string;\n  impaCode: string;\n  criticality: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';\n  status: 'OPERATIONAL' | 'MAINTENANCE' | 'STANDBY' | 'OUT_OF_SERVICE';\n  /** \uc5b4\ub290 \ud544\ub4dc\uac00 fallback\uc73c\ub85c \ucc44\uc6cc\uc84c\ub294\uc9c0 \u2014 \uac80\uc218 \ud050(\u00a71.3 mapping_status='PENDING_REVIEW') \ub178\ucd9c\uc6a9 */\n  fallbackFields: string[];\n  /** \ud558\ub098\ub77c\ub3c4 fallback\uc774 \uc788\uc73c\uba74 true \u2014 UI\uc5d0\uc11c \"\uac80\ud1a0 \ud544\uc694\" \ubc30\uc9c0 \ub80c\ub354\ub9c1 \ud2b8\ub9ac\uac70 */\n  needsReview: boolean;\n}\n\n/**\n * staging_legacy_assets \uc6d0\ubcf8(\uacf5\ubc31 \uac00\ub2a5)\uc744 \ubc1b\uc544, \uc808\ub300 \ud06c\ub798\uc2dc\ud558\uc9c0 \uc54a\ub294\n * \uc644\uc804\ud55c SafeAssetView\ub85c \ubcc0\ud658\ud55c\ub2e4. DB \uc4f0\uae30 \uc5c6\uc74c (\uc77d\uae30 \uc804\uc6a9).\n */\nexport function toSafeAssetView(row: StagingAssetRowInput): SafeAssetView {\n  const fallbackFields: string[] = [];\n\n  const equipmentTag = resolveEquipmentTag(row.proposedEquipmentTag, row.legacyTag, row.legacyName);\n  if (equipmentTag.isFallback) fallbackFields.push('equipmentTag');\n\n  const kksCode = resolveKksCode(row.proposedKksCode);\n  if (kksCode.isFallback) fallbackFields.push('kksCode');\n\n  const iso14224Class = resolveIso14224Class(row.proposedIso14224Class, row.legacyTypeFilter);\n  if (iso14224Class.isFallback) fallbackFields.push('iso14224Class');\n\n  const impaCode = resolveImpaCode(row.proposedImpaCode ?? row.legacyImpaCodeRaw);\n  if (impaCode.isFallback) fallbackFields.push('impaCode');\n\n  const criticality = resolveCriticality(row.proposedCriticality ?? row.legacyCriticalityRaw);\n  if (criticality.isFallback) fallbackFields.push('criticality');\n\n  const status = resolveStatus(row.legacyStatusRaw);\n  if (status.isFallback) fallbackFields.push('status');\n\n  return {\n    equipmentTag: equipmentTag.value,\n    assetName: isBlank(row.legacyName) ? PENDING_LABEL : row.legacyName!.trim(),\n    locationArea: isBlank(row.legacyLocationRaw) ? PENDING_LABEL : row.legacyLocationRaw!.trim(),\n    manufacturer: isBlank(row.legacyMaker) ? PENDING_LABEL : row.legacyMaker!.trim(),\n    kksCode: kksCode.value,\n    iso14224Class: iso14224Class.value,\n    impaCode: impaCode.value,\n    criticality: criticality.value,\n    status: status.value,\n    fallbackFields,\n    needsReview: fallbackFields.length > 0,\n  };\n}\n\n/** \uc5ec\ub7ec \ud589 \uc77c\uad04 \ubcc0\ud658 (staging \ud14c\uc774\ube14 SELECT \uacb0\uacfc\ub97c \uadf8\ub300\ub85c \ub123\uc744 \uc218 \uc788\uc74c) */\nexport function toSafeAssetViewList(rows: StagingAssetRowInput[]): SafeAssetView[] {\n  return rows.map(toSafeAssetView);\n}\n\n/**\n * \uac80\ud1a0 \ud544\uc694 \uc790\uc0b0\ub9cc \uace8\ub77c\ub0b4\ub294 \ud5ec\ud37c \u2014 Refactoring Plan Phase 0/1\uc758\n * \"PENDING_REVIEW \ud050\uc789\" \uc791\uc5c5\uc5d0 \uadf8\ub300\ub85c \uc0ac\uc6a9 \uac00\ub2a5.\n */\nexport function filterNeedsReview(views: SafeAssetView[]): SafeAssetView[] {\n  return views.filter((v) => v.needsReview);\n}\n",
  "src/adapters/assetStagingWriter.ts": "// src/adapters/assetStagingWriter.ts\n//\n// PURPOSE\n//   assetAdapter.ts\ub294 \uc758\ub3c4\uc801\uc73c\ub85c \"\uc77d\uae30 \uc804\uc6a9\" \uacc4\uc57d\uc744 \uc720\uc9c0\ud55c\ub2e4 (\ud30c\uc77c \uc0c1\ub2e8 GUARANTEES:\n//   \"DB \uc4f0\uae30, \ub124\ud2b8\uc6cc\ud06c \ud638\ucd9c, \uc0c1\ud0dc \ubcc0\uacbd \uc5c6\uc74c\"). \uc774 \ud30c\uc77c\uc774 \uadf8 \uacb0\uacfc\uac12(SafeAssetView)\uc744\n//   \uc2e4\uc81c\ub85c staging_legacy_assets\uc5d0 \uc801\uc7ac\ud558\ub294 \ucc45\uc784\uc744 \ubd84\ub9ac\ud574\uc11c \ub2f4\ub2f9\ud55c\ub2e4.\n//   (permitPersistenceAdapter.ts\uac00 ptwStatusMapper.ts\uc758 \uc21c\uc218 \uacc4\uc0b0\uacfc \uc601\uc18d\ud654\ub97c\n//   \ubd84\ub9ac\ud55c \uac83\uacfc \ub3d9\uc77c\ud55c \ud328\ud134.)\n//\n// IDEMPOTENCY (Phase 0 \ub9e4\uc77c \uc7ac\uc2e4\ud589 \ub300\ube44)\n//   \uac19\uc740 legacy_tag\uac00 \ub9e4\uc77c \uc7ac\uc801\uc7ac\ub418\uc5b4 staging \ud14c\uc774\ube14\uc774 \ubb34\ud55c\uc815 \ubd88\uc5b4\ub098\ub294 \uac83\uc744 \ub9c9\uae30 \uc704\ud574,\n//   \"\uc544\uc9c1 PROMOTED/REJECTED \ub418\uc9c0 \uc54a\uc740 \ucd5c\uc2e0 \ud589\"\uc774 \uc788\uc73c\uba74 \uadf8 \ud589\uc744 UPDATE\ud558\uace0,\n//   \uc5c6\uc73c\uba74(\ucd5c\ucd08\uc774\uac70\ub098 \uc774\ubbf8 PROMOTED\ub41c \uacbd\uc6b0) \uc0c8 \ud589\uc744 INSERT\ud55c\ub2e4.\n//   \uc774\ubbf8 PROMOTED\ub41c legacy_tag\ub294 \uc7ac\uc791\uc131\ud558\uc9c0 \uc54a\uace0 \uc2a4\ud0b5\uc73c\ub85c \ubcf4\uace0\ud55c\ub2e4 \u2014 \uc815\uc2dd assets\n//   \ud14c\uc774\ube14\ub85c \uc2b9\uaca9\ub41c \uc790\uc0b0\uc758 \uc2a4\ud14c\uc774\uc9d5 \uc774\ub825\uc744 \ub418\ub3cc\ub9ac\uc9c0 \uc54a\uae30 \uc704\ud568\uc774\ub2e4.\n\nimport type { SqlExecutor } from './db/sqlExecutor';\nimport { toSafeAssetView, type StagingAssetRowInput, type SafeAssetView } from './assetAdapter';\nimport { normalizeTag } from './tagNormalizationService';\nimport { resolveSystemCodeForLegacyTag } from './locationToSystemCode';\n\nexport type StagingWriteOutcome = 'INSERTED' | 'UPDATED' | 'SKIPPED_ALREADY_PROMOTED';\n\nexport interface StagingWriteResult {\n  legacyTag: string;\n  outcome: StagingWriteOutcome;\n  view: SafeAssetView;\n}\n\ninterface ExistingStagingRow {\n  staging_id: number;\n  mapping_status: string;\n}\n\nconst FIND_LATEST_SQL = `\n  SELECT staging_id, mapping_status\n  FROM staging_legacy_assets\n  WHERE legacy_tag = @legacyTag\n  ORDER BY created_at DESC\n  LIMIT 1\n`;\n\nconst INSERT_SQL = `\n  INSERT INTO staging_legacy_assets (\n    legacy_tag, legacy_name, legacy_location_raw, legacy_maker,\n    legacy_criticality_raw, legacy_status_raw, legacy_type_filter, legacy_impa_code_raw,\n    proposed_equipment_tag, proposed_kks_code, proposed_iso14224_class, proposed_criticality, proposed_impa_code,\n    mapping_status, needs_review, source_file_key\n  ) VALUES (\n    @legacyTag, @legacyName, @legacyLocationRaw, @legacyMaker,\n    @legacyCriticalityRaw, @legacyStatusRaw, @legacyTypeFilter, @legacyImpaCodeRaw,\n    @proposedEquipmentTag, @proposedKksCode, @proposedIso14224Class, @proposedCriticality, @proposedImpaCode,\n    @mappingStatus, @needsReview, @sourceFileKey\n  )\n`;\n\nconst UPDATE_SQL = `\n  UPDATE staging_legacy_assets SET\n    legacy_name = @legacyName,\n    legacy_location_raw = @legacyLocationRaw,\n    legacy_maker = @legacyMaker,\n    legacy_criticality_raw = @legacyCriticalityRaw,\n    legacy_status_raw = @legacyStatusRaw,\n    legacy_type_filter = @legacyTypeFilter,\n    legacy_impa_code_raw = @legacyImpaCodeRaw,\n    proposed_equipment_tag = @proposedEquipmentTag,\n    proposed_kks_code = @proposedKksCode,\n    proposed_iso14224_class = @proposedIso14224Class,\n    proposed_criticality = @proposedCriticality,\n    proposed_impa_code = @proposedImpaCode,\n    mapping_status = @mappingStatus,\n    needs_review = @needsReview,\n    source_file_key = @sourceFileKey,\n    updated_at = STRFTIME('%Y-%m-%dT%H:%M:%fZ','now')\n  WHERE staging_id = @stagingId\n`;\n\n/**\n * \ub2e8\uc77c \ub808\uac70\uc2dc \uc790\uc0b0 \ud589\uc744 \uc548\uc804 \ubcc0\ud658(assetAdapter.toSafeAssetView) \ud6c4\n * staging_legacy_assets\uc5d0 \uba71\ub4f1\uc801\uc73c\ub85c \ubc18\uc601\ud55c\ub2e4.\n *\n * \"PROMOTED\" \uc0c1\ud0dc\uc778 legacy_tag\ub294 \uc808\ub300 \ub36e\uc5b4\uc4f0\uc9c0 \uc54a\ub294\ub2e4 \u2014 \uc774\ubbf8 assets \ud14c\uc774\ube14\ub85c\n * \uc2b9\uaca9\ub418\uc5b4 asset_tag_alias\ub85c \ucc38\uc870\ub418\uace0 \uc788\uc744 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4.\n */\nexport function upsertStagingAssetRow(\n  db: SqlExecutor,\n  input: StagingAssetRowInput & { legacyTag: string; sourceFileKey?: string }\n): StagingWriteResult {\n  const view = toSafeAssetView(input);\n\n  // Tag Normalization: legacy_tag + location -> systemCode -> normalizeTag\n  // (ISO Tank \uac19\uc740 \uc774\ub3d9\uc2dd \uc790\uc0b0\uc740 location \ud14d\uc2a4\ud2b8 \ub300\uc2e0 \ud0dc\uadf8 prefix\ub85c System 10 \uac15\uc81c)\n  const systemCodeInfo = resolveSystemCodeForLegacyTag(input.legacyTag, input.legacyLocationRaw);\n  const normResult = normalizeTag(input.legacyTag, systemCodeInfo.systemCode, input.legacyTypeFilter ?? undefined);\n\n  // needsReview \uac8c\uc774\ud2b8: assetAdapter\uc758 fallbackFields \uc911 'impaCode'\ub294 \uc81c\uc678\ud55c\ub2e4.\n  // IMPA(\uc790\uc7ac \uce74\ud0c8\ub85c\uadf8) \ucf54\ub4dc\ub294 MRO/\uad6c\ub9e4 \ub3c4\uba54\uc778 \uad00\uc2ec\uc0ac\uc774\uc9c0 \uc790\uc0b0 \uc815\uccb4\uc131(Tag/KKS/Class/\n  // Criticality) \ub9e4\ud551 \ud488\uc9c8\uacfc \ubb34\uad00\ud558\ub2e4 \u2014 IMPA \ubbf8\ub9e4\ud551\ub9cc\uc73c\ub85c \uc790\uc0b0 \uc2b9\uaca9 \uc790\uccb4\ub97c \ub9c9\uc73c\uba74\n  // \uc2e4\uc9c8\uc801\uc73c\ub85c \ubaa8\ub4e0 \uc790\uc0b0\uc774 \uc601\uc6d0\ud788 PENDING_REVIEW\uc5d0 \uba38\ubb34\ub974\uac8c \ub418\uc5b4 \uac8c\uc774\ud2b8\uac00 \ubb34\uc758\ubbf8\ud574\uc9c4\ub2e4.\n  const blockingFallbacks = view.fallbackFields.filter((f) => f !== 'impaCode');\n  const hasReviewNeeded = blockingFallbacks.length > 0 || normResult.hasFallback;\n  const mappingStatus = hasReviewNeeded ? 'PENDING_REVIEW' : 'AUTO_MAPPED';\n  const needsReview = hasReviewNeeded ? 1 : 0;\n\n  const params = {\n    legacyTag: input.legacyTag,\n    legacyName: input.legacyName ?? null,\n    legacyLocationRaw: input.legacyLocationRaw ?? null,\n    legacyMaker: input.legacyMaker ?? null,\n    legacyCriticalityRaw: input.legacyCriticalityRaw ?? null,\n    legacyStatusRaw: input.legacyStatusRaw ?? null,\n    legacyTypeFilter: input.legacyTypeFilter ?? null,\n    legacyImpaCodeRaw: input.legacyImpaCodeRaw ?? null,\n    // proposed_* \uceec\ub7fc:\n    //   - equipmentTag/kksCode\ub294 \uc774\uc81c tagNormalizationService\ub85c \uc790\ub3d9 \uc0dd\uc131\n    //   - iso14224Class/criticality/impaCode\ub294 \uc5ec\uc804\ud788 assetAdapter \uacb0\uacfc \uc0ac\uc6a9\n    proposedEquipmentTag: normResult.hasFallback ? null : normResult.equipmentTag,\n    proposedKksCode: normResult.hasFallback ? null : normResult.kksCode,\n    proposedIso14224Class: view.fallbackFields.includes('iso14224Class') ? null : view.iso14224Class,\n    proposedCriticality: view.fallbackFields.includes('criticality') ? null : view.criticality,\n    proposedImpaCode: view.fallbackFields.includes('impaCode') ? null : view.impaCode,\n    mappingStatus,\n    needsReview,\n    sourceFileKey: input.sourceFileKey ?? null,\n  };\n\n  const existing = db.get<ExistingStagingRow>(FIND_LATEST_SQL, { legacyTag: input.legacyTag });\n\n  if (existing?.mapping_status === 'PROMOTED') {\n    return { legacyTag: input.legacyTag, outcome: 'SKIPPED_ALREADY_PROMOTED', view };\n  }\n\n  if (existing) {\n    // UPDATE_SQL\uc740 legacy_tag\ub97c SET\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c(\ubd88\ubcc0 \uc2dd\ubcc4\uc790), \ubc14\uc778\ub529 \ud30c\ub77c\ubbf8\ud130\ub3c4\n    // legacyTag\ub97c \uc81c\uc678\ud55c UPDATE_SQL \ucc38\uc870 \uceec\ub7fc\ub9cc \uc815\ud655\ud788 \ub9de\ucdb0\uc11c \uc804\ub2ec\ud574\uc57c \ud55c\ub2e4.\n    // (node:sqlite / better-sqlite3 \ub4f1 \ub2e4\uc218\uc758 \ub4dc\ub77c\uc774\ubc84\uac00 SQL\uc5d0 \uc5c6\ub294 named parameter\ub97c\n    // \ub118\uae30\uba74 \uc5c4\uaca9\ud558\uac8c \uc5d0\ub7ec\ub97c \ub358\uc9c4\ub2e4 \u2014 spread\ub85c \ud1b5\uc9f8\ub85c \ub118\uae30\uc9c0 \uc54a\ub3c4\ub85d \uc8fc\uc758)\n    const { legacyTag, ...updateParams } = params;\n    db.run(UPDATE_SQL, { ...updateParams, stagingId: existing.staging_id });\n    return { legacyTag: input.legacyTag, outcome: 'UPDATED', view };\n  }\n\n  db.run(INSERT_SQL, params);\n  return { legacyTag: input.legacyTag, outcome: 'INSERTED', view };\n}\n",
  "src/adapters/locationToSystemCode.ts": "// src/adapters/locationToSystemCode.ts\n//\n// PURPOSE\n//   \ub808\uac70\uc2dc location_raw (\uc790\uc720\ud14d\uc2a4\ud2b8, \uc608: \"Vaporizer Area\") \u2192\n//   CMMS System Code (\uc608: \"20\") \uc790\ub3d9 \ub9e4\ud551.\n//   Tag Normalization\uc758 \uc785\ub825\uc73c\ub85c \uc0ac\uc6a9\ub428.\n//\n// \uae30\uc900: P&ID NIAS-PS-PI-0002 (\uac01 System Code\ubcc4 \uc124\ube44 \ubc30\uce58\ub3c4)\n// \ucc38\uace0: Refactoring Plan \u00a71.2, \ud0dc\uadf8 \uaddc\uce59 \ud655\uc815 \ubb38\uc11c\n\nexport interface SystemCodeInfo {\n  systemCode: string;\n  systemName: string;\n}\n\nexport const LOCATION_AREA_TO_SYSTEM_CODE: Record<string, SystemCodeInfo> = {\n  // System 10: Jetty & Offloading\n  'Jetty Area': { systemCode: '10', systemName: 'Jetty & Offloading' },\n  'LNG ISO Tank Unloading Area': { systemCode: '10', systemName: 'Jetty & Offloading' },\n  'LNG ISO Tank Storage Area': { systemCode: '10', systemName: 'Jetty & Offloading' },\n  'Offloading Bay': { systemCode: '10', systemName: 'Jetty & Offloading' },\n  'ISO Tank Yard': { systemCode: '10', systemName: 'Jetty & Offloading' },\n\n  // System 20: Regasification & BOG Compression\n  'Vaporizer Area': { systemCode: '20', systemName: 'Regasification & BOG Compression' },\n  'BOG Compressor Area': { systemCode: '20', systemName: 'Regasification & BOG Compression' },\n  'Electrical MCC & Substation': { systemCode: '20', systemName: 'Regasification & BOG Compression' },\n  'Regasification Plant': { systemCode: '20', systemName: 'Regasification & BOG Compression' },\n  'Compressor Station': { systemCode: '20', systemName: 'Regasification & BOG Compression' },\n\n  // System 30: Gas Metering & Distribution\n  'Gas Metering Area': { systemCode: '30', systemName: 'Gas Metering & Distribution' },\n  'Metering Skid Area': { systemCode: '30', systemName: 'Gas Metering & Distribution' },\n  'Distribution Header': { systemCode: '30', systemName: 'Gas Metering & Distribution' },\n\n  // \ucd94\uac00 \uc124\ube44 \uc601\uc5ed (\ud655\uc7a5\uc6a9)\n  // System 40: Utilities (\uc784\uc2dc - \ud544\uc694\uc2dc \ucd94\uac00)\n  // System 50: Safety Systems (\uc784\uc2dc - \ud544\uc694\uc2dc \ucd94\uac00)\n};\n\n/**\n * location \ud14d\uc2a4\ud2b8\ub85c\ubd80\ud130 System Code\ub97c \uc870\ud68c\ud55c\ub2e4.\n * \uc77c\uce58\ud558\uc9c0 \uc54a\uc73c\uba74 fallback \"20\" (Regasification & BOG Compression) \ubc18\ud658.\n */\nexport function resolveSystemCode(location: string | null | undefined): SystemCodeInfo {\n  if (!location) return { systemCode: '20', systemName: 'Regasification & BOG Compression (Default)' };\n  const found = LOCATION_AREA_TO_SYSTEM_CODE[location.trim()];\n  if (found) return found;\n  return { systemCode: '20', systemName: 'Regasification & BOG Compression (Default - Unknown Location)' };\n}\n\n/**\n * \uc774\ub3d9\uc2dd \uc790\uc0b0(ISO Tank \ub4f1) \uc5ec\ubd80\ub97c legacy_tag prefix\ub85c \ud310\ubcc4\ud558\ub294 \ubaa9\ub85d.\n * \ud0dc\uadf8 \uaddc\uce59 \ud655\uc815 \ubb38\uc11c \u00a74: \"\uacf5\ud1b5 \uc601\uc5ed\uc778 \uacbd\uc6b0 System 10(Jetty & Offloading) \uc801\uc6a9\".\n * ISO Tank\ub294 Ship/Yard/Regas Bay \ub4f1\uc744 \uc624\uac00\ub294 \uc774\ub3d9\uc2dd \uc790\uc0b0\uc774\ub77c \uace0\uc815 location\n * \ud14d\uc2a4\ud2b8(\"Ship\", \"MV. SAVIOUR\" \ub4f1)\ub85c\ub294 System\uc744 \ud310\ub2e8\ud560 \uc218 \uc5c6\uc5b4, \ud0dc\uadf8 \uc790\uccb4\ub85c\n * \ud310\ubcc4\ud574 System 10\uc744 \uac15\uc81c \uc801\uc6a9\ud55c\ub2e4.\n */\nconst MOBILE_ASSET_TAG_PREFIXES = ['ISOT', 'ISO'];\n\n/**\n * legacy_tag\uc640 location\uc744 \ud568\uaed8 \uace0\ub824\ud574 System Code\ub97c \uacb0\uc815\ud55c\ub2e4.\n * assetStagingWriter.ts\uac00 \uc774 \ud568\uc218\ub97c \ud1b5\ud574 System Code\ub97c \uad6c\ud574\uc57c \ud55c\ub2e4\n * (resolveSystemCode\ub97c location\ub9cc\uc73c\ub85c \uc9c1\uc811 \ud638\ucd9c\ud558\uba74 \uc774\ub3d9\uc2dd \uc790\uc0b0 \uaddc\uce59\uc774 \uc801\uc6a9\ub418\uc9c0 \uc54a\uc74c).\n */\nexport function resolveSystemCodeForLegacyTag(\n  legacyTag: string,\n  location: string | null | undefined\n): SystemCodeInfo {\n  const prefix = legacyTag.trim().split(/[-_\\s]/)[0]?.toUpperCase();\n  if (prefix && MOBILE_ASSET_TAG_PREFIXES.includes(prefix)) {\n    return { systemCode: '10', systemName: 'Jetty & Offloading (Mobile Asset Default)' };\n  }\n  return resolveSystemCode(location);\n}\n",
  "src/adapters/promoteStagingAssetToAssets.ts": "// src/adapters/promoteStagingAssetToAssets.ts\n//\n// PURPOSE\n//   staging_legacy_assets \ud589\uc744 \uc2e4\uc81c assets + asset_tag_alias \ud14c\uc774\ube14\ub85c\n//   \uc2b9\uaca9\ud558\ub294 \uc601\uc18d\ud654 \ub85c\uc9c1. Phase 0\uc5d0\uc11c staging\ud55c \ud6c4, \uc0ac\ub78c\uc774 \uac80\ud1a0/\ud655\uc815\ud55c\n//   \ub370\uc774\ud130\ub97c \uc815\uc2dd CMMS \ud14c\uc774\ube14\ub85c \uc62e\uae30\ub294 \ub2e8\uacc4.\n//\n// \uc815\ucc45\n//   mapping_status='AUTO_MAPPED': \uac80\ud1a0 \ubd88\ud544\uc694 \u2192 \uc989\uc2dc \uc2b9\uaca9\n//   mapping_status='MANUAL_OVERRIDE': \uc0ac\ub78c\uc774 \uac80\ud1a0 \ud6c4 \uc218\uc815 \u2192 \uc2b9\uaca9 \uac00\ub2a5\n//   mapping_status='PENDING_REVIEW': \uc544\uc9c1 \ud655\uc815 \uc548 \ub428 \u2192 \uc2a4\ud0b5\n//   mapping_status='PROMOTED': \uc774\ubbf8 \uc2b9\uaca9 \u2192 \uc2a4\ud0b5\n//   mapping_status='REJECTED': \uac70\uc808\ub428 \u2192 \uc2a4\ud0b5\n\nimport type { SqlExecutor } from './db/sqlExecutor';\nimport { resolveStatus } from './assetAdapter';\n\ninterface PromotableRow {\n  staging_id: number;\n  legacy_tag: string;\n  legacy_name: string;\n  proposed_equipment_tag: string | null;\n  proposed_kks_code: string | null;\n  proposed_iso14224_class: string | null;\n  proposed_criticality: string | null;\n  proposed_impa_code: string | null;\n  legacy_location_raw: string | null;\n  legacy_maker: string | null;\n  legacy_status_raw: string | null;\n  mapping_status: string;\n}\n\nexport interface PromoteResult {\n  promotedCount: number;\n  skippedCount: number;\n  failureCount: number;\n  errors: { legacyTag: string; message: string }[];\n}\n\n/**\n * staging_legacy_assets\uc5d0\uc11c \uc2b9\uaca9 \uac00\ub2a5\ud55c \ud589(AUTO_MAPPED / MANUAL_OVERRIDE)\uc744\n * \uc870\ud68c\ud55c\ub2e4. proposed_equipment_tag\uac00 NULL\uc774\uba74 \uc2b9\uaca9 \ubd88\uac00 (proposed_* \uceec\ub7fc\uc774\n * \uc644\uc804\ud788 \ucc44\uc6cc\uc838\uc57c assets \ud14c\uc774\ube14 NOT NULL \uc81c\uc57d\uc744 \ud1b5\uacfc).\n */\nfunction fetchPromotableStagingRows(db: SqlExecutor): PromotableRow[] {\n  return db.all<PromotableRow>(\n    `SELECT staging_id, legacy_tag, legacy_name, proposed_equipment_tag, proposed_kks_code,\n            proposed_iso14224_class, proposed_criticality, proposed_impa_code,\n            legacy_location_raw, legacy_maker, legacy_status_raw, mapping_status\n     FROM staging_legacy_assets\n     WHERE mapping_status IN ('AUTO_MAPPED', 'MANUAL_OVERRIDE')\n       AND proposed_equipment_tag IS NOT NULL\n     ORDER BY created_at ASC`\n  );\n}\n\nconst INSERT_ASSET_SQL = `\n  INSERT INTO assets (\n    equipment_tag, asset_name, iso_14224_class, kks_code, criticality, location_area, status, manufacturer\n  ) VALUES (\n    @equipmentTag, @assetName, @iso14224Class, @kksCode, @criticality, @locationArea, @status, @manufacturer\n  )\n`;\n\nconst INSERT_ALIAS_SQL = `\n  INSERT INTO asset_tag_alias (legacy_tag, equipment_tag)\n  VALUES (@legacyTag, @equipmentTag)\n`;\n\nconst MARK_PROMOTED_SQL = `\n  UPDATE staging_legacy_assets\n  SET mapping_status = 'PROMOTED', updated_at = STRFTIME('%Y-%m-%dT%H:%M:%fZ','now')\n  WHERE staging_id = @stagingId\n`;\n\n/**\n * \ub2e8\uc77c staging \ud589\uc744 assets + asset_tag_alias\ub85c \uc2b9\uaca9\ud55c\ub2e4.\n * \uc2e4\ud328\ud574\ub3c4 \ub2e4\ub978 \ud589 \ucc98\ub9ac\ub294 \uacc4\uc18d\ud55c\ub2e4 (fault-tolerant).\n */\nfunction promoteOneRow(db: SqlExecutor, row: PromotableRow): { success: boolean; error?: string } {\n  try {\n    // status\ub294 staging\uc5d0 proposed_status \uceec\ub7fc\uc774 \uc5c6\uc5b4(\u00a7DDL) \uc5ec\uae30\uc11c legacy_status_raw\ub85c\ubd80\ud130\n    // \uc9c1\uc811 \uc7ac\uacc4\uc0b0\ud55c\ub2e4. \uc774 \uacc4\uc0b0 \uc5c6\uc774 INSERT\uc5d0\uc11c status\ub97c \uc0dd\ub7b5\ud558\uba74 DB DEFAULT('OPERATIONAL')\uac00\n    // \uc870\uc6a9\ud788 \uc801\uc6a9\ub418\uc5b4, staging \ub2e8\uacc4\uc5d0\uc11c \"\uc0c1\ud0dc \ubbf8\ud655\uc778 -> \ubcf4\uc218\uc801\uc73c\ub85c OUT_OF_SERVICE\"\ub77c\uace0\n    // \ud310\ub2e8\ud588\ub358 \uac83\uc774 \uc2b9\uaca9 \uc21c\uac04 \uc0ac\ub77c\uc9c0\uace0 \uc804\ubd80 \uc6b4\uc601\uc911\uc73c\ub85c \ub4a4\ubc14\ub010\ub2e4 \u2014 \uc2e4\uc81c Dual Read \uac80\uc99d\n    // \uc911 \uc7ac\ud604\ub418\uc5b4 \ubc1c\uacac\ud55c \ubc84\uadf8. resolveStatus()\ub85c \ub3d9\uc77c\ud55c \ubcf4\uc218\uc801 \uc815\ucc45\uc744 \uc2b9\uaca9 \uc2dc\uc810\uc5d0\ub3c4 \uc801\uc6a9\ud55c\ub2e4.\n    const status = resolveStatus(row.legacy_status_raw).value;\n\n    // assets \ud14c\uc774\ube14\uc5d0 \uc2e0\uaddc \ud589 \uc0bd\uc785\n    db.run(INSERT_ASSET_SQL, {\n      equipmentTag: row.proposed_equipment_tag,\n      assetName: row.legacy_name,\n      iso14224Class: row.proposed_iso14224_class ?? 'Unknown',\n      kksCode: row.proposed_kks_code,\n      criticality: row.proposed_criticality ?? 'MEDIUM',\n      locationArea: row.legacy_location_raw ?? 'Unknown',\n      status,\n      manufacturer: row.legacy_maker ?? null,\n    });\n\n    // asset_tag_alias \uc0bd\uc785 (legacy_tag <-> equipment_tag \ub9e4\ud551)\n    db.run(INSERT_ALIAS_SQL, {\n      legacyTag: row.legacy_tag,\n      equipmentTag: row.proposed_equipment_tag,\n    });\n\n    // staging \ud589 \uc0c1\ud0dc PROMOTED\ub85c \ubcc0\uacbd\n    db.run(MARK_PROMOTED_SQL, { stagingId: row.staging_id });\n\n    return { success: true };\n  } catch (err) {\n    return { success: false, error: err instanceof Error ? err.message : String(err) };\n  }\n}\n\n/**\n * staging_legacy_assets\uc5d0\uc11c AUTO_MAPPED/MANUAL_OVERRIDE \uc0c1\ud0dc\uc778 \ud589\ub4e4\uc744\n * \ud55c \ubc30\uce58\ub85c assets \ud14c\uc774\ube14\ub85c \uc2b9\uaca9\ud55c\ub2e4.\n *\n * \uc774 \ud568\uc218\ub97c \ud638\ucd9c\ud558\ub294 \ucabd\uc5d0\uc11c DB \ud2b8\ub79c\uc7ad\uc158\uc73c\ub85c \uac10\uc2f8\uae30\ub97c \uad8c\uc7a5\ud55c\ub2e4\n * (\uc77c\ubd80 \ud589 \uc2e4\ud328 \uc2dc\uc5d0\ub3c4 \uc131\uacf5\ud55c \ud589\uc740 \ucee4\ubc0b\ud558\ub824\uba74 \uac01 \ud589\uc744 \uac1c\ubcc4 try-catch\ub85c \ucc98\ub9ac).\n */\nexport function promoteStagingAssetsToAssets(db: SqlExecutor): PromoteResult {\n  const result: PromoteResult = {\n    promotedCount: 0,\n    skippedCount: 0,\n    failureCount: 0,\n    errors: [],\n  };\n\n  const rows = fetchPromotableStagingRows(db);\n  for (const row of rows) {\n    const res = promoteOneRow(db, row);\n    if (res.success) {\n      result.promotedCount++;\n    } else {\n      result.failureCount++;\n      result.errors.push({ legacyTag: row.legacy_tag, message: res.error ?? 'Unknown error' });\n    }\n  }\n\n  return result;\n}\n\n/**\n * \ube44\uad50: \ud604\uc7ac staging \uc0c1\ud0dc\ub97c \uc694\uc57d\uc73c\ub85c \uc870\ud68c (\ub9ac\ud3ec\ud2b8/\ubaa8\ub2c8\ud130\ub9c1\uc6a9).\n */\nexport function getStagingStatsSummary(db: SqlExecutor) {\n  const summary = db.get<{ status: string; cnt: number; detail: string }>(\n    `SELECT \n       'Summary' as status,\n       (SELECT COUNT(*) FROM staging_legacy_assets) as cnt,\n       'Total rows in staging' as detail`\n  );\n\n  const byCounts = db.all<{ mapping_status: string; cnt: number }>(\n    `SELECT mapping_status, COUNT(*) as cnt FROM staging_legacy_assets GROUP BY mapping_status`\n  );\n\n  return { summary, byCounts };\n}\n",
  "src/adapters/tagNormalizationService.ts": "// src/adapters/tagNormalizationService.ts\n//\n// PURPOSE\n//   Refactoring Plan \u00a71.2 + \ud0dc\uadf8 \uaddc\uce59 \ud655\uc815 \uad6c\ud604.\n//   \ub808\uac70\uc2dc \ud0dc\uadf8(\uc608: \"AAV-104\", \"T-201\") \u2192 CMMS equipment_tag + kks_code \uc0dd\uc131.\n//   \uc21c\uc218 \ud568\uc218, side-effect \uc5c6\uc74c.\n//\n// \uaddc\uce59\n//   equipment_tag: NIAS-[System Code]-[Equipment Category]-[Sequence]\n//   kks_code: [System Code][Equipment Category][Sequence]\n//\n// \uc608\uc2dc\n//   AAV-104 + location=\"Vaporizer Area\" \n//   \u2192 equipment_tag=\"NIAS-20-VP-104\", kks_code=\"20VP104\"\n\n// ============================================================================\n// 0. \uc6d0\ubcf8 \ud0dc\uadf8 \ud45c\uae30 \uc815\uaddc\ud654 (\uc2e4\uc81c CSV\uc758 \ud45c\uae30 \ud63c\uc7ac \ubc29\uc5b4)\n// ============================================================================\n\n/**\n * \ub808\uac70\uc2dc \ud0dc\uadf8 \ud45c\uae30\ub97c \uc815\ub9ac\ud55c\ub2e4. \uc2e4\uc81c CSV\uc5d0\uc11c \"ISOT - 1\"\ucc98\ub7fc \ud558\uc774\ud508 \uc55e\ub4a4\uc5d0\n * \uacf5\ubc31\uc774 \ub4e4\uc5b4\uac04 \uacbd\uc6b0(\"ISOT-026\"\uacfc \ud45c\uae30\uac00 \ub2e4\ub984)\ub97c \ud1b5\uc77c\ud55c\ub2e4.\n * \uc774 \ud568\uc218\ub294 legacyTag \uc790\uccb4(\uc790\uc5f0\ud0a4\ub85c \uc4f0\uc774\ub294 \ubb38\uc790\uc5f4)\ub97c \uc815\ub9ac\ud558\ub294 \uc6a9\ub3c4\uc774\ubbc0\ub85c,\n * \ub370\uc774\ud130 \uc18c\uc2a4 \ub2e8\uc5d0\uc11c legacyTag\ub97c \ub9cc\ub4e4 \ub54c \ubc18\ub4dc\uc2dc \uac70\uccd0\uc57c \ud55c\ub2e4.\n */\nexport function normalizeTagFormat(raw: string): string {\n  return raw\n    .trim()\n    .replace(/\\s*-\\s*/g, '-') // \"ISOT - 1\" -> \"ISOT-1\"\n    .replace(/\\s+/g, ' ');\n}\n\n// ============================================================================\n// 1. Equipment Category \ub9e4\ud551\n// ============================================================================\n\n/** \ub808\uac70\uc2dc \ud0dc\uadf8 prefix \ub610\ub294 Equipment Type \u2192 2\uae00\uc790 Category Code */\nconst EQUIPMENT_CATEGORY_MAP: Record<string, string> = {\n  // Vaporizer\n  AAV: 'VP',\n  VAP: 'VP',\n  // LNG ISO Tank\n  ISOT: 'TK',\n  // Vessel / Buffer Tank\n  V: 'VS',\n  // Compressor\n  CP: 'CP',\n  // Pump\n  P: 'PP',\n  PMP: 'PP',\n  // Metering Skid\n  M: 'FE', // \ub610\ub294 ME (\ud604\uc7ac\ub294 FE\ub85c \uae30\ubcf8)\n  // Vent Stack\n  VT: 'VT',\n  // Generator\n  GEN: 'GE',\n  // Pressure Regulator\n  PRSS: 'PR',\n  PRV: 'PR',\n  // LNG Tank (SHEET 2)\n  T: 'TK',\n};\n\n/**\n * \ub808\uac70\uc2dc \ud0dc\uadf8\uc758 prefix\ub97c \ubcf4\uace0 Equipment Category Code(2\uae00\uc790)\ub97c \ucc3e\ub294\ub2e4.\n * \uc608: \"AAV-104\" \u2192 prefix \"AAV\" \u2192 \"VP\"\n *\n * \uc77c\uce58\ud558\uc9c0 \uc54a\uc73c\uba74 fallback \"XX\" \ubc18\ud658 (\ub098\uc911\uc5d0 mapping_status='PENDING_REVIEW'\ub85c \ud45c\uc2dc)\n */\nexport function resolveEquipmentCategoryCode(\n  legacyTag: string,\n  explicitType?: string // \uba85\uc2dc\uc801 \uc9c0\uc815(\uc6b0\uc120\uc21c\uc704 \ub192\uc74c)\n): { code: string; isFallback: boolean } {\n  if (explicitType) {\n    const code = EQUIPMENT_CATEGORY_MAP[explicitType];\n    if (code) return { code, isFallback: false };\n  }\n\n  const cleanTag = normalizeTagFormat(legacyTag);\n  const parts = cleanTag.split(/[-_]/);\n  const prefix = (parts[0] ?? '').trim();\n  const code = EQUIPMENT_CATEGORY_MAP[prefix];\n  if (code) return { code, isFallback: false };\n\n  return { code: 'XX', isFallback: true };\n}\n\n// ============================================================================\n// 2. Sequence \ucd94\ucd9c\n// ============================================================================\n\n/**\n * \ub808\uac70\uc2dc \ud0dc\uadf8\uc5d0\uc11c \uc77c\ub828\ubc88\ud638\ub97c \ucd94\ucd9c\ud55c\ub2e4.\n * \uc608: \"AAV-104\" \u2192 \"104\", \"T-201\" \u2192 \"201\", \"PRSS-01\" \u2192 \"01\"\n *\n * \uaddc\uce59: \ud558\uc774\ud508(-) \ub4a4\uc758 \uc5f0\uc18d\ub41c \uc22b\uc790, \ub610\ub294 \ubb38\uc790\uc5f4 \ub05d\uc758 \uc5f0\uc18d\ub41c \uc22b\uc790\ub97c \ucd94\ucd9c.\n * 3~4\uc790\ub9ac\uac00 \uae30\ubcf8\uc774\uc9c0\ub9cc, 2\uc790\ub9ac(\"01\") \uac19\uc740 \uc9e7\uc740 \uac83\ub3c4 \ud5c8\uc6a9(\uc55e\uc5d0 0 \ucc44\uc6b0\uc9c0 \uc54a\uc74c \u2014 \uc6d0\ubcf8 \uadf8\ub300\ub85c).\n */\nexport function extractSequence(legacyTag: string): { sequence: string; isFallback: boolean } {\n  const match = legacyTag.match(/[-_]?(\\d{1,4})$/);\n  if (match && match[1]) {\n    return { sequence: match[1], isFallback: false };\n  }\n  return { sequence: '0000', isFallback: true };\n}\n\n// ============================================================================\n// 3. \ud1b5\ud569: \ub808\uac70\uc2dc \ud0dc\uadf8 \u2192 equipment_tag + kks_code\n// ============================================================================\n\nexport interface TagNormalizationResult {\n  equipmentTag: string;\n  kksCode: string;\n  systemCode: string;\n  categoryCode: string;\n  sequence: string;\n  hasFallback: boolean; // category \ub610\ub294 sequence\uac00 fallback\uc778 \uacbd\uc6b0 true\n}\n\n/**\n * \ub808\uac70\uc2dc \ud0dc\uadf8(\uc608: \"AAV-104\")\ub97c CMMS \ud0dc\uadf8\ub85c \uc815\uaddc\ud654\ud55c\ub2e4.\n *\n * @param legacyTag \uc6d0\ubcf8 \ud0dc\uadf8 (\uc608: \"AAV-104\")\n * @param systemCode Location \uae30\ubc18 \ub9e4\ud551\uc5d0\uc11c \uc628 System Code (\uc608: \"20\")\n * @param explicitType \uba85\uc2dc\uc801 Equipment Type (optional, ISO14224Class \ub4f1\uc5d0\uc11c \uc624\uac70\ub098 \uc0ac\uc6a9\uc790 \uc785\ub825)\n * @returns equipment_tag, kks_code, \uadf8\ub9ac\uace0 \uc0ac\uc6a9\ub41c fallback \uc5ec\ubd80\n */\nexport function normalizeTag(\n  legacyTag: string,\n  systemCode: string,\n  explicitType?: string\n): TagNormalizationResult {\n  const category = resolveEquipmentCategoryCode(legacyTag, explicitType);\n  const seq = extractSequence(legacyTag);\n\n  const plant = 'NIAS'; // \uace0\uc815\n  const equipmentTag = `${plant}-${systemCode}-${category.code}-${seq.sequence}`;\n  const kksCode = `${systemCode}${category.code}${seq.sequence}`;\n\n  return {\n    equipmentTag,\n    kksCode,\n    systemCode,\n    categoryCode: category.code,\n    sequence: seq.sequence,\n    hasFallback: category.isFallback || seq.isFallback,\n  };\n}\n\n/**\n * \uc5ec\ub7ec \ub808\uac70\uc2dc \ud0dc\uadf8\ub97c \uc77c\uad04 \uc815\uaddc\ud654\ud55c\ub2e4 (batch \ucc98\ub9ac\uc6a9).\n */\nexport function normalizeTagsBatch(\n  tags: Array<{ legacyTag: string; systemCode: string; explicitType?: string }>\n): TagNormalizationResult[] {\n  return tags.map((t) => normalizeTag(t.legacyTag, t.systemCode, t.explicitType));\n}\n",
  "src/adapters/db/sqlExecutor.ts": "// src/adapters/db/sqlExecutor.ts\n//\n// PURPOSE\n//   gasSafetyAdapter.ts / permitPersistenceAdapter.ts\uac00 \uacf5\ud1b5\uc73c\ub85c \uc0ac\uc6a9\ud558\ub294\n//   \ucd5c\uc18c DB \uc2e4\ud589 \uc778\ud130\ud398\uc774\uc2a4. \ud2b9\uc815 \ub4dc\ub77c\uc774\ubc84(better-sqlite3, node:sqlite,\n//   Prisma \ub4f1)\uc5d0 \uc885\uc18d\ub418\uc9c0 \uc54a\ub3c4\ub85d \ucd94\uc0c1\ud654\ud55c\ub2e4.\n//\n//   \uc2e4\uc81c \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c\ub294 \uc774 \uc778\ud130\ud398\uc774\uc2a4\ub97c \ub9cc\uc871\ud558\ub294 \uc5b4\ub311\ud130\ub97c \ud55c \ubc88\ub9cc \uad6c\ud604\ud574\uc11c\n//   \uc8fc\uc785\ud558\uba74 \ub41c\ub2e4. \uc608:\n//\n//     import Database from 'better-sqlite3';\n//     const raw = new Database('nias_cmms.db');\n//     const db: SqlExecutor = {\n//       run: (sql, params) => { raw.prepare(sql).run(params ?? {}); },\n//       get: (sql, params) => raw.prepare(sql).get(params ?? {}) as any,\n//       all: (sql, params) => raw.prepare(sql).all(params ?? {}) as any,\n//     };\n//\n//   \ud14c\uc2a4\ud2b8/\uc0cc\ub4dc\ubc15\uc2a4 \ud658\uacbd\uc5d0\uc11c\ub294 \uc774 \ud30c\uc77c \ud558\ub2e8\uc758 createInMemoryFakeExecutor()\ub85c\n//   \ub300\uccb4\ud574 \ub85c\uc9c1\ub9cc \uac80\uc99d\ud560 \uc218 \uc788\ub2e4 (\ud504\ub85c\ub355\uc158 \uc0ac\uc6a9 \uae08\uc9c0 \u2014 \uc601\uc18d\uc131 \uc5c6\uc74c).\n\nexport interface SqlExecutor {\n  /** INSERT/UPDATE/DELETE \ub4f1 \uacb0\uacfc row\ub97c \ubc18\ud658\ud558\uc9c0 \uc54a\ub294 \uc4f0\uae30 \uc2e4\ud589 */\n  run(sql: string, params?: Record<string, unknown>): void;\n  /** \ub2e8\uc77c row \uc870\ud68c */\n  get<T = Record<string, unknown>>(sql: string, params?: Record<string, unknown>): T | undefined;\n  /** \ub2e4\uc911 row \uc870\ud68c */\n  all<T = Record<string, unknown>>(sql: string, params?: Record<string, unknown>): T[];\n}\n\n/**\n * \uc21c\uc218 \uc778\uba54\ubaa8\ub9ac Fake \uad6c\ud604\uccb4 \u2014 \ub2e8\uc704\ud14c\uc2a4\ud2b8/\ub85c\uc9c1 \uac80\uc99d \uc804\uc6a9.\n * \uc2e4\uc81c SQL\uc744 \ud30c\uc2f1\ud558\uc9c0 \uc54a\uace0, \ud14c\uc774\ube14\ubcc4 \ubc30\uc5f4\uc5d0 \ub2e8\uc21c \uc800\uc7a5\ub9cc \ud55c\ub2e4.\n * gasSafetyAdapter.ts / permitPersistenceAdapter.ts\uc758 \uc790\uccb4 \ud14c\uc2a4\ud2b8\uc5d0\uc11c\ub9cc \uc0ac\uc6a9\ud55c\ub2e4.\n */\nexport function createInMemoryFakeExecutor() {\n  const tables: Record<string, Record<string, unknown>[]> = {};\n\n  function tableNameFromInsert(sql: string): string | null {\n    const m = /INSERT\\s+INTO\\s+(\\w+)/i.exec(sql);\n    return m ? m[1] : null;\n  }\n\n  const executor: SqlExecutor & { _tables: typeof tables } = {\n    _tables: tables,\n    run(sql, params = {}) {\n      const table = tableNameFromInsert(sql);\n      if (!table) return; // UPSERT/UPDATE \ub4f1\uc740 \uc774 fake\uc5d0\uc11c\ub294 no-op (permitPersistenceAdapter \ud14c\uc2a4\ud2b8\uc5d0\uc11c \ubcc4\ub3c4 \ucc98\ub9ac)\n      if (!tables[table]) tables[table] = [];\n      tables[table].push({ ...params });\n    },\n    get(sql, params = {}) {\n      const table = /FROM\\s+(\\w+)/i.exec(sql)?.[1];\n      if (!table || !tables[table]) return undefined;\n      return tables[table][tables[table].length - 1] as any;\n    },\n    all(sql, params = {}) {\n      const table = /FROM\\s+(\\w+)/i.exec(sql)?.[1];\n      if (!table || !tables[table]) return [];\n      return tables[table] as any[];\n    },\n  };\n  return executor;\n}\n",
  "src/adapters/db/nodeSqliteExecutor.ts": "// src/adapters/db/nodeSqliteExecutor.ts\n//\n// PURPOSE\n//   SqlExecutor \uc778\ud130\ud398\uc774\uc2a4\uc758 \ub808\ud37c\ub7f0\uc2a4 \uad6c\ud604\uccb4. Node.js 22+ \ub0b4\uc7a5\n//   `node:sqlite`(DatabaseSync)\ub97c \uc0ac\uc6a9\ud558\ubbc0\ub85c \ubcc4\ub3c4 npm \uc758\uc874\uc131(better-sqlite3 \ub4f1)\n//   \uc5c6\uc774 \ubc14\ub85c \ub3d9\uc791\ud55c\ub2e4. Phase 1 \uac80\uc99d/\ub85c\uceec \uac1c\ubc1c\uc6a9\uc73c\ub85c \uc6b0\uc120 \uc81c\uacf5\ud558\uba70,\n//   \ud504\ub85c\ub355\uc158 \ubc30\ud3ec \ud658\uacbd\uc758 Node \ubc84\uc804 \uc815\ucc45\uc5d0 \ub530\ub77c better-sqlite3 \ub4f1\uc73c\ub85c\n//   \uad50\uccb4\ud574\ub3c4 SqlExecutor \uc778\ud130\ud398\uc774\uc2a4\ub9cc \ub9cc\uc871\ud558\uba74 \ub098\uba38\uc9c0 \uc5b4\ub311\ud130 \ucf54\ub4dc\ub294 \ubb34\uc218\uc815\uc774\ub2e4.\n//\n// \uc8fc\uc758: node:sqlite\ub294 \uc544\uc9c1 Experimental API\ub2e4 (Node 22 \uae30\uc900). \uc548\uc815\ud654 \uc804\uae4c\uc9c0\ub294\n//       \ud504\ub85c\ub355\uc158\uc5d0\uc11c \uc774 \ud30c\uc77c \ub300\uc2e0 better-sqlite3 \uae30\ubc18 \uad6c\ud604\uccb4 \uc0ac\uc6a9\uc744 \uad8c\uc7a5\ud55c\ub2e4.\n\nimport { DatabaseSync } from 'node:sqlite';\nimport type { SqlExecutor } from './sqlExecutor';\n\nexport function createNodeSqliteExecutor(dbPath: string): SqlExecutor & { close(): void; raw: DatabaseSync } {\n  const raw = new DatabaseSync(dbPath);\n  raw.exec('PRAGMA foreign_keys = ON;');\n\n  return {\n    raw,\n    run(sql, params = {}) {\n      raw.prepare(sql).run(params as Record<string, unknown>);\n    },\n    get<T = Record<string, unknown>>(sql: string, params: Record<string, unknown> = {}): T | undefined {\n      return raw.prepare(sql).get(params) as T | undefined;\n    },\n    all<T = Record<string, unknown>>(sql: string, params: Record<string, unknown> = {}): T[] {\n      return raw.prepare(sql).all(params) as T[];\n    },\n    close() {\n      raw.close();\n    },\n  };\n}\n\n/** \uc2a4\ud0a4\ub9c8 \ud30c\uc77c(schema/cmms_schema.sqlite.sql) \uc804\uccb4\ub97c \uadf8\ub300\ub85c \uc2e4\ud589\ud558\ub294 \ud5ec\ud37c */\nexport function loadSchema(raw: DatabaseSync, schemaSql: string): void {\n  raw.exec(schemaSql);\n}\n",
  "src/data/legacyDataSource.ts": "// src/batch/legacyDataSource.ts\n//\n// PURPOSE\n//   Phase 0 Shadow Write \ubc30\uce58\uac00 \"\ub808\uac70\uc2dc \ub370\uc774\ud130\ub97c \uc5b4\ub514\uc11c \uc77d\uc5b4\uc624\ub294\uc9c0\"\ub97c \ucd94\uc0c1\ud654\ud55c\ub2e4.\n//   \ud604\uc7ac \uc2dc\uc810(2026-09)\uc5d0\ub294 \uc2e4\uc81c \uc5f0\ub3d9 \uc18c\uc2a4\uac00 \ubbf8\uc815\uc774\ubbc0\ub85c, \uc778\ud130\ud398\uc774\uc2a4\ub9cc \ud655\uc815\ud558\uace0\n//   \uac80\uc99d/\ub85c\uceec \uac1c\ubc1c\uc6a9 \ucc38\uc870 \uad6c\ud604\uccb4(JsonFileLegacyDataSource) \ud558\ub098\ub9cc \uc81c\uacf5\ud55c\ub2e4.\n//\n//   \uc2e4 \uc5f0\ub3d9 \uc2dc \uc544\ub798 \uc14b \uc911 \ud558\ub098\ub85c \uad50\uccb4\ud558\uba74 \ub418\uba70, shadowWriteBatch.ts \ub4f1 \uc774 \uc778\ud130\ud398\uc774\uc2a4\ub97c\n//   \uc18c\ube44\ud558\ub294 \ucf54\ub4dc\ub294 \ud55c \uc904\ub3c4 \ubc14\ub00c\uc9c0 \uc54a\ub294\ub2e4:\n//     - PortalDataContext\ub97c \uc11c\ubc84(API route)\uc5d0\uc11c \uc870\ud68c\ud558\ub294 \uad6c\ud604\uccb4\n//     - \ub808\uac70\uc2dc DB\uc5d0 \uc9c1\uc811 \uc5f0\uacb0\ud558\ub294 \uad6c\ud604\uccb4\n//     - \ub808\uac70\uc2dc CSV\ub97c \ud30c\uc2f1\ud558\ub294 \uad6c\ud604\uccb4\n//\n//   \uc774 \ud30c\uc77c \uc790\uccb4\ub294 DB\uc5d0 \uc4f0\uc9c0 \uc54a\ub294\ub2e4 (\uc77d\uae30 \uc804\uc6a9 \uc18c\uc2a4 \ucd94\uc0c1\ud654).\n\nimport { readFileSync, existsSync } from 'node:fs';\nimport type { StagingAssetRowInput } from '../adapters/assetAdapter';\n\n// \ud5c8\uac00\uc11c(PTW) \uad00\ub828 \uac00\uc2a4\uce21\uc815 \ud0c0\uc785\uc740 \uc9c0\uae08 \ub2e8\uacc4\uc5d0\uc11c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4(\ubaa8\ub4e0\n// LegacyDataSource \uad6c\ud604\uccb4\uac00 fetchPermits()\uc5d0\uc11c \ube48 \ubc30\uc5f4\ub9cc \ubc18\ud658). \uc6d0\ub798\ub294\n// '../adapters/gasSafetyAdapter'\uc758 LegacyGasReadings\ub97c \uc7ac\uc0ac\uc6a9\ud588\uc73c\ub098,\n// \uadf8 \ud30c\uc77c\uc744 \uc544\uc9c1 \uc774 \ud504\ub85c\uc81d\ud2b8\uc5d0 \ub4e4\uc774\uc9c0 \uc54a\uc558\uc73c\ubbc0\ub85c \ucd5c\uc18c \ud615\ud0dc\ub85c \ub85c\uceec \uc815\uc758\ud574\n// \ubd88\ud544\uc694\ud55c \uc758\uc874\uc131\uc744 \uc5c6\uc564\ub2e4. e-PTW/\uac00\uc2a4\uce21\uc815 \uc5f0\ub3d9\uc744 \uc2dc\uc791\ud560 \ub54c\n// gasSafetyAdapter.ts\ub97c \ub4e4\uc5ec\uc624\uba74\uc11c \uc774 \ub85c\uceec \ud0c0\uc785\uc744 \uadf8\uac78\ub85c \ubc14\uafd4\uce58\uae30\ud558\uba74 \ub41c\ub2e4.\ninterface LegacyGasReadings {\n  lelPercent: number;\n  o2Percent: number;\n  h2sPpm: number;\n  coPpm?: number;\n  testedAt: string;\n  isSafeForWork: boolean;\n}\n\n// ----------------------------------------------------------------------------\n// 1. \uc778\ud130\ud398\uc774\uc2a4 (\uc2e4 \uc5f0\ub3d9 \uc2dc \uc774 \ud615\ud0dc\ub9cc \ub9cc\uc871\uc2dc\ud0a4\uba74 \ub428)\n// ----------------------------------------------------------------------------\n\n/** \ub808\uac70\uc2dc \uc790\uc0b0 1\uac74 \u2014 assetStagingWriter.upsertStagingAssetRow()\uc758 \uc785\ub825\uacfc \ud638\ud658 */\nexport interface LegacyAssetSourceRow extends StagingAssetRowInput {\n  legacyTag: string; // staging PK \ub300\uc6a9 \uc790\uc5f0\ud0a4\uc774\ubbc0\ub85c \ud544\uc218\n  sourceFileKey?: string; // \uc774 \ud589\uc774 \uc5b4\ub290 \uc6d0\ubcf8 \ud30c\uc77c/\uc18c\uc2a4\uc5d0\uc11c \uc654\ub294\uc9c0 \ucd94\uc801\uc6a9 (\uc120\ud0dd)\n}\n\n/** \ub808\uac70\uc2dc PTW permit 1\uac74 \u2014 Shadow Write \ub300\uc0c1 \ucd5c\uc18c \uc815\ubcf4 */\nexport interface LegacyPermitSourceRow {\n  /** \ub808\uac70\uc2dc PTWPermit.id (\uc608: \"PTW-2026-0901-01\") */\n  permitRefNo: string;\n  /** payloadHash \uacc4\uc0b0\uc5d0 \uc0ac\uc6a9\ud560 permit \uc804\uccb4 payload (\ud574\uc2dc \uc548\uc815\uc131\uc744 \uc704\ud574 \ub9e4 \uc2e4\ud589 \ub3d9\uc77c shape \uc720\uc9c0 \ud544\uc694) */\n  payload: unknown;\n  /** \uc774\ubc88 \ubc30\uce58 \uc2dc\uc810\uc5d0 \ud568\uaed8 \uc801\uc7ac\ud560 \ucd5c\uc2e0 \uac00\uc2a4\uce21\uc815\uac12 (\uc5c6\uc73c\uba74 \uc0dd\ub7b5) */\n  latestGasReading?: LegacyGasReadings;\n  /** \uac00\uc2a4\uce21\uc815 \ub2f4\ub2f9\uc790 \uc2dd\ubcc4\uc790 (latestGasReading\uc774 \uc788\uc744 \ub54c \ud544\uc218) */\n  testerIdentifier?: string;\n}\n\nexport interface LegacyDataSource {\n  fetchAssets(): Promise<LegacyAssetSourceRow[]> | LegacyAssetSourceRow[];\n  fetchPermits(): Promise<LegacyPermitSourceRow[]> | LegacyPermitSourceRow[];\n}\n\n// ----------------------------------------------------------------------------\n// 2. \ucc38\uc870 \uad6c\ud604\uccb4 \u2014 JSON \ud30c\uc77c \uae30\ubc18 (\ub85c\uceec \uac80\uc99d / \uc2e4 \uc5f0\ub3d9 \uc804 \uc784\uc2dc \ub300\uccb4\uc6a9)\n// ----------------------------------------------------------------------------\n\n/**\n * assets.json / permits.json \ub450 \ud30c\uc77c\uc744 \uc77d\uc5b4 LegacyDataSource\ub97c \uad6c\ud604\ud55c\ub2e4.\n * \uc2e4 \uc5f0\ub3d9 \uc804\uae4c\uc9c0 \ubc30\uce58 \ud30c\uc774\ud504\ub77c\uc778 \uc790\uccb4(\uc801\uc7ac \ub85c\uc9c1, \ub9ac\ud3ec\ud2b8 \uc0dd\uc131)\ub97c \uac80\uc99d\ud558\ub294 \uc6a9\ub3c4.\n *\n * \uae30\ub300 \ud30c\uc77c \ud615\uc2dd:\n *   assets.json  : LegacyAssetSourceRow[]\n *   permits.json : LegacyPermitSourceRow[]\n */\nexport class JsonFileLegacyDataSource implements LegacyDataSource {\n  constructor(private readonly assetsJsonPath: string, private readonly permitsJsonPath: string) {}\n\n  fetchAssets(): LegacyAssetSourceRow[] {\n    if (!existsSync(this.assetsJsonPath)) return [];\n    const raw = readFileSync(this.assetsJsonPath, 'utf8');\n    return JSON.parse(raw) as LegacyAssetSourceRow[];\n  }\n\n  fetchPermits(): LegacyPermitSourceRow[] {\n    if (!existsSync(this.permitsJsonPath)) return [];\n    const raw = readFileSync(this.permitsJsonPath, 'utf8');\n    return JSON.parse(raw) as LegacyPermitSourceRow[];\n  }\n}\n\n/**\n * \uc544\uc9c1 \uc544\ubb34 \uc18c\uc2a4\ub3c4 \uc5f0\uacb0\ub418\uc9c0 \uc54a\uc558\uc74c\uc744 \uba85\uc2dc\uc801\uc73c\ub85c \ub4dc\ub7ec\ub0b4\ub294 Null Object.\n * shadowWriteBatch\ub97c \uc18c\uc2a4 \uc5c6\uc774\ub3c4 \"0\uac74 \ucc98\ub9ac\"\ub85c \uc548\uc804\ud558\uac8c \ub3cc\ub824\ubcfc \uc218 \uc788\uac8c \ud574\uc900\ub2e4.\n * \uc2e4 \uc5f0\ub3d9 \uc804\uae4c\uc9c0 \uae30\ubcf8\uac12\uc73c\ub85c \uc0ac\uc6a9 \uac00\ub2a5.\n */\nexport class UnconnectedLegacyDataSource implements LegacyDataSource {\n  fetchAssets(): LegacyAssetSourceRow[] {\n    return [];\n  }\n  fetchPermits(): LegacyPermitSourceRow[] {\n    return [];\n  }\n}\n\n// ----------------------------------------------------------------------------\n// 3. \ub2e4\uc911 \uc18c\uc2a4 \ud569\uc131 \u2014 ISO Tank(\uc2e4 \ub370\uc774\ud130) + \uace0\uc815\uc124\ube44(\ud50c\ub808\uc774\uc2a4\ud640\ub354) \ub4f1 \uc5ec\ub7ec\n//    LegacyDataSource\ub97c \ud558\ub098\ub85c \ubb36\uc5b4 Phase 0/1 \ubc30\uce58\uc5d0 \ub2e8\uc77c \uc18c\uc2a4\ub85c \uacf5\uae09\ud55c\ub2e4.\n// ----------------------------------------------------------------------------\n\n/**\n * \uc5ec\ub7ec LegacyDataSource\ub97c \uc21c\uc11c\ub300\ub85c \ud638\ucd9c\ud574 \uacb0\uacfc\ub97c \ud569\uce5c\ub2e4.\n * \uac19\uc740 legacy_tag\uac00 \ub458 \uc774\uc0c1\uc758 \uc18c\uc2a4\uc5d0 \ub098\ud0c0\ub098\uba74 (\uc774\ub860\uc0c1 \uc788\uc5b4\uc11c\ub294 \uc548 \ub418\uc9c0\ub9cc)\n * \ub4a4\uc5d0 \ub098\uc5f4\ub41c \uc18c\uc2a4\uc758 \uac12\uc73c\ub85c \ub36e\uc5b4\uc368\uc9c4\ub2e4 \u2014 \uc6b0\uc120\uc21c\uc704\uac00 \ud544\uc694\ud558\uba74 \ubc30\uc5f4 \uc21c\uc11c\ub85c \uc870\uc808.\n */\nexport class CompositeLegacyDataSource implements LegacyDataSource {\n  constructor(private readonly sources: LegacyDataSource[]) {}\n\n  async fetchAssets(): Promise<LegacyAssetSourceRow[]> {\n    const byTag = new Map<string, LegacyAssetSourceRow>();\n    for (const source of this.sources) {\n      const rows = await source.fetchAssets();\n      for (const row of rows) byTag.set(row.legacyTag, row);\n    }\n    return Array.from(byTag.values());\n  }\n\n  async fetchPermits(): Promise<LegacyPermitSourceRow[]> {\n    const all: LegacyPermitSourceRow[] = [];\n    for (const source of this.sources) {\n      all.push(...(await source.fetchPermits()));\n    }\n    return all;\n  }\n}\n\n// ----------------------------------------------------------------------------\n// 4. \uacf5\ud1b5 \uc18c\uc2a4 \uacb0\uc815 \ub85c\uc9c1 \u2014 runPhase0.ts\uc640 runPhase1DualRead.ts\uac00 \ubc18\ub4dc\uc2dc\n//    \uc774 \ud568\uc218 \ud558\ub098\ub9cc \uacf5\uc720\ud574\uc11c \uc368\uc57c \ud55c\ub2e4. \uac01 \uc2a4\ud06c\ub9bd\ud2b8\uac00 \uc774 \ub85c\uc9c1\uc744 \ub530\ub85c\n//    \ubca0\uaef4 \uc4f0\uba74(\uc2e4\uc81c\ub85c \ud55c \ubc88 \uadf8\ub807\uac8c \ud588\ub2e4\uac00 \uc11c\ub85c \ub2e4\ub978 \uacb0\uacfc\uac00 \ub098\ub294 \ubc84\uadf8\uac00 \ub0ac\uc5c8\ub2e4)\n//    \ub450 \ubc30\uce58\uac00 \uc11c\ub85c \ub2e4\ub978 \ub370\uc774\ud130\ub97c \ubcf4\ub294 \ucc44\ub85c \uc870\uc6a9\ud788 \uac08\ub77c\uc9c8 \uc218 \uc788\ub2e4.\n//\n//    \ub3d9\uc801 import\ub85c IsoTankLegacyDataSource/FixedEquipmentLegacyDataSource\ub97c\n//    \ubd88\ub7ec\uc628\ub2e4 \u2014 legacyDataSource.ts \uc790\uccb4\ub294 \ub450 \uad6c\ud604\uccb4\ub97c \ubab0\ub77c\ub3c4 \ub418\uac8c(\uc21c\ud658\n//    \uc758\uc874 \ubc29\uc9c0) \ud558\uae30 \uc704\ud568\uc774\ub2e4.\n// ----------------------------------------------------------------------------\n\nexport async function resolveConfiguredDataSource(): Promise<LegacyDataSource> {\n  // 1\uc21c\uc704: \uba85\uc2dc\uc801 JSON override (\ud14c\uc2a4\ud2b8/\ud2b9\uc218 \ubaa9\uc801)\n  const assetsJson = process.env.LEGACY_ASSETS_JSON;\n  const permitsJson = process.env.LEGACY_PERMITS_JSON;\n  if (assetsJson && permitsJson) {\n    return new JsonFileLegacyDataSource(assetsJson, permitsJson);\n  }\n\n  // 2\uc21c\uc704: \uc2e4 \ub370\uc774\ud130 \uc18c\uc2a4 \ud569\uc131\n  //   - ISO Tank: \uc2e4 CSV \ud544\uc218 (\uc5c6\uc73c\uba74 unconnected)\n  //   - \uace0\uc815\uc124\ube44: FIXED_EQUIPMENT_CSV\uac00 \uc788\uace0 \uc2e4\uc81c \ud30c\uc77c\uc774 \uc874\uc7ac\ud558\uba74 \uadf8\uac78 \uc6b0\uc120 \uc0ac\uc6a9.\n  //     \uc5c6\uc73c\uba74(\ud50c\ub79c\ud2b8 \uac74\uc124 \ub9c8\ubb34\ub9ac \ub2e8\uacc4\ub77c \uc544\uc9c1 \ud655\uc815 \uc2a4\ud399\uc774 \uc5c6\ub294 \uacbd\uc6b0) \uc790\ub3d9\uc73c\ub85c\n  //     MockFixedEquipmentDataSource\ub85c \ub300\uccb4\ud55c\ub2e4 \u2014 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\uc2dc \ubb3b\uc9c0 \uc54a\uace0,\n  //     \uc778\ud504\ub77c/UI\uac00 \ud56d\uc0c1 \ub3d9\uc791\ud558\ub294 \uc0c1\ud0dc\ub97c \uc720\uc9c0\ud558\ub294 \uac83\uc774 \uc774 \ub2e8\uacc4\uc758 \uc6b0\uc120\uc21c\uc704\uc774\uae30 \ub54c\ubb38.\n  //     \ub098\uc911\uc5d0 FIXED_EQUIPMENT_CSV\ub97c \uc2e4\uc81c \ud30c\uc77c \uacbd\ub85c\ub85c \uc9c0\uc815\ud558\uae30\ub9cc \ud558\uba74 \ucf54\ub4dc \ubcc0\uacbd\n  //     \uc5c6\uc774 \uc774 mock\uc740 \uc790\ub3d9\uc73c\ub85c \uc2e4 \ub370\uc774\ud130\ub85c \uad50\uccb4\ub41c\ub2e4.\n  const isoStatusCsv = process.env.ISO_TANK_STATUS_LOCATION_CSV;\n  const isoMasterCsv = process.env.ISO_TANK_MASTER_DB_CSV; // optional\n  const fixedEquipmentCsv = process.env.FIXED_EQUIPMENT_CSV; // optional\n\n  if (isoStatusCsv) {\n    const { IsoTankLegacyDataSource } = await import('./isoTankLegacyDataSource');\n    const sources: LegacyDataSource[] = [new IsoTankLegacyDataSource(isoStatusCsv, isoMasterCsv)];\n\n    if (fixedEquipmentCsv && existsSync(fixedEquipmentCsv)) {\n      const { FixedEquipmentLegacyDataSource } = await import('./fixedEquipmentLegacyDataSource');\n      sources.push(new FixedEquipmentLegacyDataSource(fixedEquipmentCsv));\n      console.log(`[legacyDataSource] \uace0\uc815\uc124\ube44 \uc2e4 CSV \uc0ac\uc6a9: ${fixedEquipmentCsv}`);\n    } else {\n      const { MockFixedEquipmentDataSource } = await import('./mockFixedEquipmentDataSource');\n      sources.push(new MockFixedEquipmentDataSource());\n      console.log('[legacyDataSource] \uace0\uc815\uc124\ube44 \uc2e4 CSV \uc5c6\uc74c \u2014 MockFixedEquipmentDataSource\ub85c \uc790\ub3d9 \ub300\uccb4 (\uac74\uc124 \uc644\ub8cc \ud6c4 CSV \uc9c0\uc815 \uc2dc \uc790\ub3d9 \uc804\ud658).');\n    }\n    return new CompositeLegacyDataSource(sources);\n  }\n\n  console.warn(\n    '[legacyDataSource] \ub370\uc774\ud130 \uc18c\uc2a4 \ud658\uacbd\ubcc0\uc218 \ubbf8\uc124\uc815(LEGACY_ASSETS_JSON \ub610\ub294 ISO_TANK_STATUS_LOCATION_CSV) \u2014 ' +\n      'UnconnectedLegacyDataSource\ub85c \uc2e4\ud589 (0\uac74 \ucc98\ub9ac \uc608\uc0c1).'\n  );\n  return new UnconnectedLegacyDataSource();\n}\n",
  "src/data/isoTankLegacyDataSource.ts": "// src/batch/isoTankLegacyDataSource.ts\n//\n// PURPOSE\n//   \uc2e4\uc81c NIAS CSV 2\uac1c\ub97c \uc77d\uc5b4 ISO Tank\ub97c CMMS \uc790\uc0b0(LegacyAssetSourceRow)\uc73c\ub85c\n//   \ud3b8\uc785\ud558\ub294 LegacyDataSource \uad6c\ud604\uccb4.\n//\n//   \uc18c\uc2a4 \ud30c\uc77c:\n//     1) \"NIAS - ISO TANK Status, Location.csv\" \u2014 \uc804\uccb4 \ud568\ub300 \ub85c\uc2a4\ud130(120\ub300,\n//        \uac01 \ud0dc\uadf8 \uc720\uc77c). \uc774\uac8c \"\uc790\uc0b0\uc774 \uc874\uc7ac\ud55c\ub2e4\"\ub294 \uc0ac\uc2e4\uc758 \uae30\uc900(source of truth for\n//        existence)\uc774\ub2e4. \uceec\ub7fc: No, ISO Tk No., Serial No., Location, Position, REMARKS\n//     2) \"NIAS - ISO Tank Master DB.csv\" \u2014 \uc77c\ubd80 \ud0f1\ud06c(\uc804\uccb4 120\ub300 \uc911 11\ub300\ub9cc)\uc758\n//        \uc2dc\uacc4\uc5f4 \ud154\ub808\uba54\ud2b8\ub9ac(Level/Pressure/Temp \ub4f1). \uc790\uc0b0 \uc874\uc7ac \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c\n//        \"\ucd5c\uadfc \uc6b4\uc6a9 \uc774\ub825\uc774 \uc788\ub294 \ud0f1\ud06c\"\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ubcf4\uc870 \ub370\uc774\ud130.\n//        \uceec\ub7fc: Report Date, Serial No., ISO Tk No., ..., Level(%), Pressure(MPa), Temp(\u00b0C), ...\n//\n//   CMMS \ud544\ub4dc \ub9e4\ud551 \uc815\ucc45 (\uc0ac\uc6a9\uc790 \ud655\uc815):\n//     - criticality: \uc6d0\ubcf8\uc5d0 \uc5c6\uc74c \u2192 null\ub85c \ub450\uc5b4 assetAdapter\uc758 \uae30\uc874 fallback\n//       (DEFAULT_CRITICALITY='MEDIUM')\uc774 \uc790\ub3d9 \uc801\uc6a9\ub418\uac8c \ud55c\ub2e4.\n//     - manufacturer: \uc6d0\ubcf8\uc5d0 \uc5c6\uc74c \u2192 null (assets.manufacturer\ub294 NULL \ud5c8\uc6a9).\n//     - iso14224Class: 'ISO_TANK'\ub85c \uba85\uc2dc \uc9c0\uc815 (fallback \uc544\ub2d8 \u2014 proposedIso14224Class\uc5d0\n//       \uc9c1\uc811 \uac12\uc744 \ucc44\uc6cc resolveIso14224Class\uac00 \uadf8\ub300\ub85c \ud1b5\uacfc\uc2dc\ud0a4\ub3c4\ub85d \ud568).\n//     - System Code: ISO Tank\ub294 \uc774\ub3d9\uc2dd \uc790\uc0b0\uc774\ubbc0\ub85c location \ud14d\uc2a4\ud2b8(\"Ship\"/\"Aceh\" \ub4f1)\n//       \ub300\uc2e0 tagNormalizationService\uc758 \uc774\ub3d9\uc2dd \uc790\uc0b0 \uaddc\uce59(prefix=\"ISOT\")\uc73c\ub85c System 10 \uace0\uc815.\n\nimport { readFileSync } from 'node:fs';\nimport { parseCsv } from '../utils/CsvUtils';\nimport { normalizeTagFormat } from '../adapters/tagNormalizationService';\nimport type { LegacyAssetSourceRow, LegacyPermitSourceRow, LegacyDataSource } from './legacyDataSource';\n\ninterface StatusLocationRow {\n  isoTkNo: string; // \uc815\uaddc\ud654\ub428 (\uc608: \"ISOT-1\")\n  serialNo: string;\n  location: string;\n  position: string;\n  remarks: string;\n}\n\ninterface MasterDbLatestRow {\n  isoTkNo: string;\n  reportDate: string;\n  levelPct?: string;\n  pressureMPa?: string;\n  tempC?: string;\n}\n\nfunction parseStatusLocationCsv(csvText: string): StatusLocationRow[] {\n  const rows = parseCsv(csvText);\n  return rows\n    .filter((r) => (r['ISO Tk No.'] ?? '').trim().length > 0)\n    .map((r) => ({\n      isoTkNo: normalizeTagFormat(r['ISO Tk No.']),\n      serialNo: (r['Serial No.'] ?? '').trim(),\n      location: (r['Location'] ?? '').trim(),\n      position: (r['Position'] ?? '').trim(),\n      remarks: (r['REMARKS'] ?? '').trim(),\n    }));\n}\n\n/** Master DB\ub294 \ud0f1\ud06c\ub2f9 \uc5ec\ub7ec \ub0a0\uc9dc \ud589\uc774 \uc788\uc73c\ubbc0\ub85c, Report Date \uae30\uc900 \ucd5c\uc2e0 1\uac74\ub9cc \ub0a8\uae34\ub2e4. */\nfunction parseMasterDbLatestPerTank(csvText: string): Map<string, MasterDbLatestRow> {\n  const rows = parseCsv(csvText);\n  const latestByTag = new Map<string, MasterDbLatestRow>();\n\n  for (const r of rows) {\n    const rawTag = r['ISO Tk No.'];\n    if (!rawTag || rawTag.trim().length === 0) continue;\n    const isoTkNo = normalizeTagFormat(rawTag);\n    const reportDate = (r['Report Date'] ?? '').trim();\n\n    const existing = latestByTag.get(isoTkNo);\n    if (!existing || reportDate > existing.reportDate) {\n      latestByTag.set(isoTkNo, {\n        isoTkNo,\n        reportDate,\n        levelPct: r['Level (%)'],\n        pressureMPa: r['Pressure (MPa)'],\n        tempC: r['Temp (\u00b0C)'],\n      });\n    }\n  }\n  return latestByTag;\n}\n\n/**\n * Status/Location \ud14d\uc2a4\ud2b8(\"Ship\" + \"MV. SAVIOUR\" \ub4f1)\ub97c \uc0ac\ub78c\uc774 \uc77d\uc744 legacyLocationRaw\n * \ubb38\uc790\uc5f4\ub85c \ud569\uc131\ud55c\ub2e4. System Code \uacb0\uc815\uc5d0\ub294 \uc4f0\uc774\uc9c0 \uc54a\ub294\ub2e4(\ud0dc\uadf8 prefix\ub85c \uacb0\uc815\ub428) \u2014\n * \uc21c\uc218 \uc815\ubcf4 \ud45c\uc2dc/\uac80\ud1a0\uc6a9.\n */\nfunction composeLocationText(row: StatusLocationRow): string {\n  if (row.position && row.position !== row.location) {\n    return `${row.location} (${row.position})`;\n  }\n  return row.location || 'Unknown';\n}\n\nexport class IsoTankLegacyDataSource implements LegacyDataSource {\n  constructor(\n    private readonly statusLocationCsvPath: string,\n    private readonly masterDbCsvPath?: string // optional \u2014 \ud154\ub808\uba54\ud2b8\ub9ac \uc5c6\uc5b4\ub3c4 \ub85c\uc2a4\ud130\ub9cc\uc73c\ub85c \ub3d9\uc791 \uac00\ub2a5\n  ) {}\n\n  fetchAssets(): LegacyAssetSourceRow[] {\n    const statusText = readFileSync(this.statusLocationCsvPath, 'utf8');\n    const roster = parseStatusLocationCsv(statusText);\n\n    const telemetryByTag = this.masterDbCsvPath\n      ? parseMasterDbLatestPerTank(readFileSync(this.masterDbCsvPath, 'utf8'))\n      : new Map<string, MasterDbLatestRow>();\n\n    return roster.map((row) => {\n      const telemetry = telemetryByTag.get(row.isoTkNo);\n      const remarksNote = telemetry\n        ? ` [\ucd5c\uadfc \ud154\ub808\uba54\ud2b8\ub9ac ${telemetry.reportDate}: Level ${telemetry.levelPct ?? 'N/A'}%, ${telemetry.tempC ?? 'N/A'}\u00b0C]`\n        : '';\n\n      const legacyRow: LegacyAssetSourceRow = {\n        legacyTag: row.isoTkNo,\n        legacyName: `ISO Tank ${row.isoTkNo} (S/N ${row.serialNo})${remarksNote}`,\n        legacyLocationRaw: composeLocationText(row),\n        legacyMaker: null, // \uc6d0\ubcf8 \ub370\uc774\ud130\uc5d0 \uc81c\uc870\uc0ac \uc815\ubcf4 \uc5c6\uc74c\n        legacyCriticalityRaw: null,\n        proposedCriticality: 'MEDIUM', // \ud655\uc815\uac12(\uc815\ucc45) \u2014 \uc6d0\ubcf8\uc5d0 criticality \uac1c\ub150 \uc790\uccb4\uac00 \uc5c6\uc5b4 fallback\uc774 \uc544\ub2cc \uba85\uc2dc\uc801 \uae30\ubcf8\uac12\uc73c\ub85c \uc9c0\uc815\n        legacyStatusRaw: null, // fallback -> OUT_OF_SERVICE (\ubcf4\uc218\uc801 \uae30\ubcf8\uac12). \uc6d0\ubcf8\uc5d0 \uac00\ub3d9\uc0c1\ud0dc \uac1c\ub150\uc774 \uc5c6\uc5b4 \uc774 \ud544\ub4dc\ub294 \uc758\ub3c4\uc801\uc73c\ub85c PENDING_REVIEW\ub97c \uc720\uc9c0\uc2dc\ud0a8\ub2e4 (\uc0ac\ub78c\uc774 \uc2e4\uc81c \uac00\ub3d9\uc0c1\ud0dc\ub97c \ud655\uc778\ud574\uc57c \ud568)\n        legacyTypeFilter: 'PLANT',\n        legacyImpaCodeRaw: null,\n        proposedIso14224Class: 'ISO_TANK', // \ud655\uc815\uac12 \u2014 fallback \uc544\ub2d8\n        sourceFileKey: 'iso_tank_status_location_csv',\n      };\n      return legacyRow;\n    });\n  }\n\n  fetchPermits(): LegacyPermitSourceRow[] {\n    // ISO Tank CSV\ub4e4\uc740 PTW/\ud5c8\uac00\uc11c \ub370\uc774\ud130\ub97c \ud3ec\ud568\ud558\uc9c0 \uc54a\ub294\ub2e4.\n    return [];\n  }\n}\n",
  "src/data/fixedEquipmentLegacyDataSource.ts": "// src/batch/fixedEquipmentLegacyDataSource.ts\n//\n// PURPOSE\n//   \uace0\uc815 \uc124\ube44(Vaporizer, Generator, Pump, Pressure Regulator \ub4f1)\uc758 \ub9c8\uc2a4\ud130\n//   \ub370\uc774\ud130\ub294 \uc544\uc9c1 \uc815\uc2dd CSV/DB\ub85c \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4 (\uc0ac\uc6a9\uc790 \ud655\uc778). \uc774 \ud30c\uc77c\uc740\n//   \ud574\ub2f9 \ub370\uc774\ud130\uac00 \ub098\uc911\uc5d0 \ucc44\uc6cc\uc9c8 \uc790\ub9ac\ub97c CMMS \uc778\ud130\ud398\uc774\uc2a4\uc5d0 \ub9de\ucdb0 \ubbf8\ub9ac \ub9cc\ub4e4\uc5b4\ub454\n//   \ud50c\ub808\uc774\uc2a4\ud640\ub354 \uad6c\ud604\uccb4\ub2e4.\n//\n//   templates/fixed_equipment_master_template.csv \uc591\uc2dd(\ud5e4\ub354 \uace0\uc815)\uc5d0 \ub9de\ucdb0\n//   \uc2e4\uc81c \uc790\uc0b0 \ubaa9\ub85d\uc744 \ucc44\uc6cc \ub123\uae30\ub9cc \ud558\uba74, \uc774 \ud074\ub798\uc2a4\uac00 \uc989\uc2dc IsoTankLegacyDataSource\uc640\n//   \ub3d9\uc77c\ud55c \ubc29\uc2dd\uc73c\ub85c Phase 0/1 \ubc30\uce58 \ud30c\uc774\ud504\ub77c\uc778\uc5d0 \ud3b8\uc785\ub41c\ub2e4 \u2014 \ucf54\ub4dc \ubcc0\uacbd \ubd88\ud544\uc694.\n//\n//   \ud15c\ud50c\ub9bf \uceec\ub7fc:\n//     legacy_tag, legacy_name, legacy_location_raw, legacy_maker,\n//     legacy_criticality_raw, legacy_status_raw, legacy_type_filter(PLANT|INSTRUMENTS)\n//\n//   criticality/maker\uac00 \ube44\uc5b4\uc788\ub294 \ud589\ub3c4 \ud5c8\uc6a9\ub41c\ub2e4 \u2014 assetAdapter\uc758 \uae30\uc874 fallback\n//   \uc815\ucc45(criticality \uc5c6\uc73c\uba74 MEDIUM, maker \uc5c6\uc73c\uba74 \ud45c\uc2dc PENDING)\uc774 \uadf8\ub300\ub85c \uc801\uc6a9\ub41c\ub2e4.\n\nimport { readFileSync, existsSync } from 'node:fs';\nimport { parseCsv } from '../utils/CsvUtils';\nimport { normalizeTagFormat } from '../adapters/tagNormalizationService';\nimport type { LegacyAssetSourceRow, LegacyPermitSourceRow, LegacyDataSource } from './legacyDataSource';\n\nfunction isBlank(v: string | undefined): boolean {\n  return !v || v.trim().length === 0;\n}\n\nexport class FixedEquipmentLegacyDataSource implements LegacyDataSource {\n  constructor(private readonly csvPath: string) {}\n\n  fetchAssets(): LegacyAssetSourceRow[] {\n    if (!existsSync(this.csvPath)) {\n      // \ud15c\ud50c\ub9bf\uc774 \uc544\uc9c1 \ucc44\uc6cc\uc9c0\uc9c0 \uc54a\uc740 \ucd08\uae30 \uc0c1\ud0dc \u2014 \uc870\uc6a9\ud788 0\uac74 \ubc18\ud658.\n      // (UnconnectedLegacyDataSource\uc640 \ub3d9\uc77c\ud55c \"\uba85\uc2dc\uc801 \ubbf8\uc5f0\uacb0\" \ucca0\ud559)\n      console.warn(\n        `[FixedEquipmentLegacyDataSource] CSV \ud30c\uc77c \uc5c6\uc74c: ${this.csvPath}. ` +\n          `templates/fixed_equipment_master_template.csv \uc591\uc2dd\uc744 \ucc38\uace0\ud574 \uc2e4\uc81c \ub370\uc774\ud130\ub97c \ucc44\uc6cc\uc8fc\uc138\uc694.`\n      );\n      return [];\n    }\n\n    const text = readFileSync(this.csvPath, 'utf8');\n    const rows = parseCsv(text);\n\n    return rows\n      .filter((r) => !isBlank(r['legacy_tag']) && !isBlank(r['legacy_name']))\n      .map((r) => {\n        const typeFilterRaw = (r['legacy_type_filter'] ?? '').trim().toUpperCase();\n        const legacyTypeFilter: 'PLANT' | 'INSTRUMENTS' | null =\n          typeFilterRaw === 'PLANT' || typeFilterRaw === 'INSTRUMENTS' ? (typeFilterRaw as 'PLANT' | 'INSTRUMENTS') : null;\n\n        const row: LegacyAssetSourceRow = {\n          legacyTag: normalizeTagFormat(r['legacy_tag']),\n          legacyName: r['legacy_name'].trim(),\n          legacyLocationRaw: isBlank(r['legacy_location_raw']) ? null : r['legacy_location_raw'].trim(),\n          legacyMaker: isBlank(r['legacy_maker']) ? null : r['legacy_maker'].trim(),\n          legacyCriticalityRaw: isBlank(r['legacy_criticality_raw']) ? null : r['legacy_criticality_raw'].trim(),\n          legacyStatusRaw: isBlank(r['legacy_status_raw']) ? null : r['legacy_status_raw'].trim(),\n          legacyTypeFilter,\n          legacyImpaCodeRaw: null,\n          sourceFileKey: 'fixed_equipment_master_csv',\n        };\n        return row;\n      });\n  }\n\n  fetchPermits(): LegacyPermitSourceRow[] {\n    return [];\n  }\n}\n",
  "src/data/mockFixedEquipmentDataSource.ts": "// src/batch/mockFixedEquipmentDataSource.ts\n//\n// PURPOSE\n//   \ud50c\ub79c\ud2b8\uac00 \uc544\uc9c1 \uac74\uc124 \ub9c8\ubb34\ub9ac \ub2e8\uacc4\ub77c \uace0\uc815\uc124\ube44(Vaporizer/Generator/Compressor \ub4f1)\n//   \ub9c8\uc2a4\ud130 \ub370\uc774\ud130\uc758 \uc815\ud655\ud55c \uc2a4\ud399\uc774 \ud655\uc815\ub418\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\uc5d0\uc11c\ub3c4, CMMS \uc778\ud504\ub77c\uc640 UI\uac00\n//   \ub3d9\uc791\ud560 \uc218 \uc788\ub3c4\ub85d \uac00\uc0c1 \uc790\uc0b0 \ub370\uc774\ud130\ub97c \uc790\ub3d9 \uc0dd\uc131\ud55c\ub2e4.\n//\n//   FixedEquipmentLegacyDataSource(CSV \uae30\ubc18)\uc640 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c LegacyDataSource\n//   \uc778\ud130\ud398\uc774\uc2a4\ub97c \uad6c\ud604\ud558\ubbc0\ub85c, \ub098\uc911\uc5d0 \uc2e4\uc81c CSV\uac00 \uc900\ube44\ub418\uba74 legacyDataSource.ts\uc758\n//   resolveConfiguredDataSource() \uc6b0\uc120\uc21c\uc704 \ub85c\uc9c1\ub9cc\uc73c\ub85c \uc790\ub3d9 \uad50\uccb4\ub41c\ub2e4 \u2014\n//   \uc774 \ud30c\uc77c\uc774\ub098 \ud638\ucd9c\ubd80 \ucf54\ub4dc\ub97c \uc190\ub308 \ud544\uc694\uac00 \uc5c6\ub2e4.\n//\n//   \uc5ec\uae30 \uc788\ub294 \ud0dc\uadf8/\uc774\ub984/\uc704\uce58\ub294 P&ID(NIAS-PS-PI-0002) \uc2dc\ud2b8 \uad6c\uc131\uc744 \ucc38\uace0\ud55c\n//   \"\uc788\uc74c\uc9c1\ud55c\" \ub300\ud45c \uc124\ube44 \ubaa9\ub85d\uc774\uba70, \uc2e4\uc81c \uc790\uc0b0 \ubaa9\ub85d\uc774 \uc544\ub2c8\ub2e4. mapping_status\ub294\n//   AUTO_MAPPED\ub85c \ub098\uac00\uc9c0 \uc54a\uace0 \ud56d\uc0c1 PENDING_REVIEW\ub85c \ub0a8\ub3c4\ub85d criticality\ub97c\n//   \ube44\uc6cc\ub454\ub2e4(=\uc9c4\uc9dc \uc790\uc0b0\uc774 \uc544\ub2c8\ub77c\ub294 \ud45c\uc2dd\uc744 \uc720\uc9c0) \u2014 \uc544\ub798 \ucc38\uace0.\n\nimport { normalizeTagFormat } from '../adapters/tagNormalizationService';\nimport type { LegacyAssetSourceRow, LegacyPermitSourceRow, LegacyDataSource } from './legacyDataSource';\n\ninterface MockEquipmentSpec {\n  legacyTag: string;\n  legacyName: string;\n  legacyLocationRaw: string;\n  legacyTypeFilter: 'PLANT' | 'INSTRUMENTS';\n}\n\n/**\n * P&ID \uc2dc\ud2b8 \uad6c\uc131(SHEET 2~8) \uae30\uc900 \ub300\ud45c \uc124\ube44 1\ub300\uc529 \u2014 \uc2e4\uc81c \uc790\uc0b0 \uc218/\uc0ac\uc591\uc774 \uc544\ub2c8\ub77c\n * \"\uc774\ub7f0 \uc885\ub958\uc758 \uc124\ube44\uac00 \uc774\ub7f0 \uc704\uce58\uc5d0 \uc788\uc744 \uac83\"\uc774\ub77c\ub294 \ubf08\ub300(\uc2a4\uce90\ud3f4\ub529) \ubaa9\uc801.\n * \uac74\uc124 \uc644\ub8cc \ud6c4 \uc2e4\uc81c \ubaa9\ub85d\uc73c\ub85c \uad50\uccb4\ub420 \ub54c\uae4c\uc9c0 UI \uac1c\ubc1c/\uc2dc\uc5f0\uc6a9.\n */\nconst MOCK_EQUIPMENT_SPECS: MockEquipmentSpec[] = [\n  { legacyTag: 'AAV-101', legacyName: '[MOCK] Ambient Air Vaporizer Skid 101', legacyLocationRaw: 'Vaporizer Area', legacyTypeFilter: 'PLANT' },\n  { legacyTag: 'CP-201', legacyName: '[MOCK] BOG Compressor 201', legacyLocationRaw: 'BOG Compressor Area', legacyTypeFilter: 'PLANT' },\n  { legacyTag: 'P-301', legacyName: '[MOCK] LNG Feed Pump 301', legacyLocationRaw: 'Vaporizer Area', legacyTypeFilter: 'PLANT' },\n  { legacyTag: 'M-401', legacyName: '[MOCK] Gas Metering Skid 401', legacyLocationRaw: 'Gas Metering Area', legacyTypeFilter: 'INSTRUMENTS' },\n  { legacyTag: 'VT-501', legacyName: '[MOCK] Vent Stack 501', legacyLocationRaw: 'Gas Metering Area', legacyTypeFilter: 'PLANT' },\n  { legacyTag: 'GEN-601', legacyName: '[MOCK] Emergency Generator 601', legacyLocationRaw: 'Electrical MCC & Substation', legacyTypeFilter: 'PLANT' },\n  { legacyTag: 'PRSS-701', legacyName: '[MOCK] Pressure Regulator Station 701', legacyLocationRaw: 'Gas Metering Area', legacyTypeFilter: 'INSTRUMENTS' },\n];\n\nexport class MockFixedEquipmentDataSource implements LegacyDataSource {\n  fetchAssets(): LegacyAssetSourceRow[] {\n    return MOCK_EQUIPMENT_SPECS.map((spec) => ({\n      legacyTag: normalizeTagFormat(spec.legacyTag),\n      legacyName: spec.legacyName,\n      legacyLocationRaw: spec.legacyLocationRaw,\n      legacyMaker: null, // \ubbf8\ud655\uc815 \u2014 \uac74\uc124 \uc644\ub8cc \ud6c4 \uc2e4 \ub370\uc774\ud130\ub85c \ucc44\uc6cc\uc9d0\n      legacyCriticalityRaw: null, // \ubbf8\ud655\uc815 \u2014 \uc758\ub3c4\uc801\uc73c\ub85c fallback(MEDIUM) \ucc98\ub9ac, PENDING_REVIEW \uc720\uc9c0\n      legacyStatusRaw: null, // \ubbf8\uc6b4\uc601 \uc0c1\ud0dc\uc774\ubbc0\ub85c OUT_OF_SERVICE fallback\uc774 \uc624\ud788\ub824 \uc815\ud655\ud568\n      legacyTypeFilter: spec.legacyTypeFilter,\n      legacyImpaCodeRaw: null,\n      sourceFileKey: 'mock_fixed_equipment',\n    }));\n  }\n\n  fetchPermits(): LegacyPermitSourceRow[] {\n    return [];\n  }\n}\n",
  "src/scripts/bootstrapAutoApproveAndPromote.ts": "// src/batch/bootstrapAutoApproveAndPromote.ts\n//\n// \u26a0 \uac1c\ubc1c/\uc2dc\uc5f0 \ub2e8\uacc4 \uc804\uc6a9. \uc6b4\uc601 \ub370\uc774\ud130\uc5d0\ub294 \uc0ac\uc6a9\ud558\uc9c0 \ub9d0 \uac83.\n//\n// PURPOSE\n//   \ud50c\ub79c\ud2b8\uac00 \uc544\uc9c1 \uac74\uc124 \ub9c8\ubb34\ub9ac \ub2e8\uacc4\ub77c \uc0ac\ub78c\uc774 \uc790\uc0b0 \ub9e4\ud551\uc744 \uac80\ud1a0\ud560 \uc2e4\uc775\uc774 \uc5c6\ub294\n//   \ud604\uc7ac \uc2dc\uc810\uc5d0 \ud55c\ud574, staging_legacy_assets\uc758 PENDING_REVIEW \ud589\uc744 \uc0ac\ub78c \uac80\ud1a0\n//   \uc5c6\uc774 \uc77c\uad04 MANUAL_OVERRIDE\ub85c \uc804\ud658\ud55c \ub4a4 \uc989\uc2dc \uc2b9\uaca9\uae4c\uc9c0 \uc9c4\ud589\ud55c\ub2e4.\n//\n//   plant\uac00 \uc2e4\uc81c \uac00\ub3d9\uc5d0 \ub4e4\uc5b4\uac00\uace0 \ub098\uba74 \uc774 \ud568\uc218 \ud638\ucd9c\uc744 \ud30c\uc774\ud504\ub77c\uc778\uc5d0\uc11c \ube7c\uace0,\n//   \uc6d0\ub798 \uc124\uacc4\ub300\ub85c(\u00a7Phase 0 \ubb38\uc11c) \uc0ac\ub78c\uc774 PENDING_REVIEW \ud050\ub97c \uc9c1\uc811 \uac80\ud1a0\ud574\n//   MANUAL_OVERRIDE\ub85c \uc804\ud658\ud558\ub294 \ud504\ub85c\uc138\uc2a4\ub85c \ub418\ub3cc\ub824\uc57c \ud55c\ub2e4 \u2014 \uc774 \ud30c\uc77c \uc0c1\ub2e8\uc758\n//   \uacbd\uace0 \uc8fc\uc11d\uc774 \uadf8 \uc804\ud658 \uc2dc\uc810\uc758 \uccb4\ud06c\ub9ac\uc2a4\ud2b8 \uc5ed\ud560\uc744 \ud55c\ub2e4.\n//\n//   proposed_equipment_tag\uac00 NULL\uc778 \ud589(Tag Normalization \uc790\uccb4\uac00 \uc2e4\ud328\ud55c \uacbd\uc6b0,\n//   \uc608: Equipment Category\ub97c \ubabb \ucc3e\uc740 \uc644\uc804\ud788 \ub0af\uc120 prefix)\uc740 \uc774 \ud568\uc218\ub3c4 \uc2b9\uaca9\n//   \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ud55c\ub2e4 \u2014 \uc774\uac83\uae4c\uc9c0 \uc790\ub3d9 \uc2b9\uc778\ud558\uba74 \"XX-0000\" \uac19\uc740 \uc758\ubbf8 \uc5c6\ub294\n//   \ud0dc\uadf8\uac00 \uc815\uc2dd assets \ud14c\uc774\ube14\uc5d0 \ub4e4\uc5b4\uac00 \ubc84\ub9b0\ub2e4.\n\nimport type { SqlExecutor } from '../adapters/db/sqlExecutor';\nimport { promoteStagingAssetsToAssets, type PromoteResult } from '../adapters/promoteStagingAssetToAssets';\n\nconst AUTO_APPROVE_SQL = `\n  UPDATE staging_legacy_assets\n  SET mapping_status = 'MANUAL_OVERRIDE',\n      reviewer_id = 'BOOTSTRAP_AUTO_APPROVE',\n      reviewed_at = STRFTIME('%Y-%m-%dT%H:%M:%fZ','now'),\n      updated_at = STRFTIME('%Y-%m-%dT%H:%M:%fZ','now')\n  WHERE mapping_status = 'PENDING_REVIEW'\n    AND proposed_equipment_tag IS NOT NULL\n`;\n\nexport interface BootstrapResult {\n  autoApprovedCount: number;\n  promoteResult: PromoteResult;\n}\n\n/**\n * reviewer_id='BOOTSTRAP_AUTO_APPROVE'\ub85c \ud45c\uc2dc\ud574\ub450\ub294 \uc774\uc720: \ub098\uc911\uc5d0 \uc2e4\uc81c \uc6b4\uc601\uc5d0\n * \ub4e4\uc5b4\uac00\uba74 `SELECT * FROM staging_legacy_assets WHERE reviewer_id =\n * 'BOOTSTRAP_AUTO_APPROVE'`\ub85c \"\uc0ac\ub78c\uc774 \uc2e4\uc81c\ub85c \ubcf8 \uc801 \uc5c6\ub294\" \uc790\uc0b0\uc744 \uac78\ub7ec\ub0b4\n * \uc7ac\uac80\ud1a0 \ub300\uc0c1\uc73c\ub85c \uc0bc\uc744 \uc218 \uc788\ub2e4.\n */\nexport function bootstrapAutoApproveAndPromote(db: SqlExecutor): BootstrapResult {\n  const before = db.get<{ cnt: number }>(\n    `SELECT COUNT(*) as cnt FROM staging_legacy_assets WHERE mapping_status = 'PENDING_REVIEW' AND proposed_equipment_tag IS NOT NULL`\n  );\n  db.run(AUTO_APPROVE_SQL);\n  const autoApprovedCount = before?.cnt ?? 0;\n\n  const promoteResult = promoteStagingAssetsToAssets(db);\n\n  return { autoApprovedCount, promoteResult };\n}\n",
  "src/scripts/exportCmmsAssetSnapshot.ts": "// src/batch/exportCmmsAssetSnapshot.ts\n//\n// PURPOSE\n//   assets \ud14c\uc774\ube14(\uc2b9\uaca9 \uc644\ub8cc\ub41c CMMS \uc790\uc0b0)\uc744 \uc815\uc801 JSON \ud30c\uc77c\ub85c \ub0b4\ubcf4\ub0b8\ub2e4.\n//   PortalDataContext.tsx \uac19\uc740 React \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 fetch()\ub85c \ubc14\ub85c \uc77d\uc744 \uc218 \uc788\ub294\n//   \ud615\ud0dc \u2014 DB \ub4dc\ub77c\uc774\ubc84\ub098 \ubc31\uc5d4\ub4dc API \uc5c6\uc774\ub3c4 \ud504\ub860\ud2b8\uc5d4\ub4dc\uac00 CMMS \uc790\uc0b0 \ub370\uc774\ud130\ub97c\n//   \uc18c\ube44\ud560 \uc218 \uc788\uac8c \ud574\uc900\ub2e4 (\ud604\uc7ac \ud3ec\ud138\uc774 \uc815\uc801 CSV/JSON\uc744 public/data/\uc5d0\uc11c\n//   \uc77d\ub294 \uae30\uc874 \uad00\ub840\uc640 \ub3d9\uc77c\ud55c \ud328\ud134).\n//\n//   \uc774 \ud30c\uc77c\uc758 \ucd9c\ub825 \uc2a4\ud0a4\ub9c8\ub294 \ub370\uc774\ud130 \ucd9c\ucc98(ISO Tank \uc2e4 CSV\ub4e0, \uace0\uc815\uc124\ube44\n//   Mock\uc774\ub4e0, \ub098\uc911\uc5d0 \uc2e4 CSV\ub85c \uad50\uccb4\ub418\ub4e0)\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ub3d9\uc77c\ud558\ub2e4 \u2014\n//   \uadf8\ub798\uc11c \"\ub098\uc911\uc5d0 \uc2e4 \ub370\uc774\ud130\ub85c \uad50\uccb4\ud574\ub3c4 \ucf54\ub4dc \uc218\uc815 \ubd88\ud544\uc694\"\uac00 \uc131\ub9bd\ud55c\ub2e4.\n//   \ud504\ub860\ud2b8\uc5d4\ub4dc\ub294 \uc624\uc9c1 \uc774 JSON \uc2a4\ud0a4\ub9c8\ub9cc \uc54c\uba74 \ub41c\ub2e4.\n\nimport { writeFileSync, mkdirSync } from 'node:fs';\nimport { dirname } from 'node:path';\nimport type { SqlExecutor } from '../adapters/db/sqlExecutor';\n\n/** \ud504\ub860\ud2b8\uc5d4\ub4dc\uac00 \uc18c\ube44\ud558\ub294 \ucd5c\uc885 \uc2a4\ud0a4\ub9c8. assets \ud14c\uc774\ube14 \uc2a4\ud0a4\ub9c8\uac00 \ubc14\ub00c\uc5b4\ub3c4\n *  \uc774 \uc778\ud130\ud398\uc774\uc2a4\ub9cc \uc720\uc9c0\ub418\uba74 \ud504\ub860\ud2b8\uc5d4\ub4dc \ucf54\ub4dc\ub294 \uc601\ud5a5\ubc1b\uc9c0 \uc54a\ub294\ub2e4. */\nexport interface CmmsAssetSnapshotRow {\n  equipmentTag: string;\n  assetName: string;\n  isoClass: string;\n  kksCode: string;\n  criticality: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';\n  locationArea: string;\n  status: 'OPERATIONAL' | 'MAINTENANCE' | 'STANDBY' | 'OUT_OF_SERVICE';\n  manufacturer: string | null;\n  parentTag: string | null;\n  /** \uc774 \uc790\uc0b0\uc774 mock/placeholder \ub370\uc774\ud130\uc778\uc9c0 \uc5ec\ubd80 \u2014 UI\uc5d0\uc11c \"\ud655\uc815 \uc804\" \ubc30\uc9c0 \ud45c\uc2dc\uc6a9.\n   *  legacy_tag\uac00 '[MOCK]'\uc73c\ub85c \uc2dc\uc791\ud558\ub294 asset_name\uc744 \uac00\uc84c\ub294\uc9c0\ub85c \ud310\ubcc4\ud55c\ub2e4. */\n  isMockData: boolean;\n}\n\nexport interface CmmsAssetSnapshotFile {\n  generatedAt: string;\n  totalCount: number;\n  assets: CmmsAssetSnapshotRow[];\n}\n\ninterface AssetRow {\n  equipment_tag: string;\n  asset_name: string;\n  iso_14224_class: string;\n  kks_code: string;\n  criticality: string;\n  location_area: string;\n  status: string;\n  manufacturer: string | null;\n  parent_tag: string | null;\n}\n\nexport function buildCmmsAssetSnapshot(db: SqlExecutor): CmmsAssetSnapshotFile {\n  const rows = db.all<AssetRow>(\n    `SELECT equipment_tag, asset_name, iso_14224_class, kks_code, criticality,\n            location_area, status, manufacturer, parent_tag\n     FROM assets ORDER BY equipment_tag`\n  );\n\n  const assets: CmmsAssetSnapshotRow[] = rows.map((r) => ({\n    equipmentTag: r.equipment_tag,\n    assetName: r.asset_name,\n    isoClass: r.iso_14224_class,\n    kksCode: r.kks_code,\n    criticality: r.criticality as CmmsAssetSnapshotRow['criticality'],\n    locationArea: r.location_area,\n    status: r.status as CmmsAssetSnapshotRow['status'],\n    manufacturer: r.manufacturer,\n    parentTag: r.parent_tag,\n    isMockData: r.asset_name.startsWith('[MOCK]'),\n  }));\n\n  return {\n    generatedAt: new Date().toISOString(),\n    totalCount: assets.length,\n    assets,\n  };\n}\n\nexport function exportCmmsAssetSnapshot(db: SqlExecutor, outputPath: string): CmmsAssetSnapshotFile {\n  const snapshot = buildCmmsAssetSnapshot(db);\n  mkdirSync(dirname(outputPath), { recursive: true });\n  writeFileSync(outputPath, JSON.stringify(snapshot, null, 2), 'utf8');\n  return snapshot;\n}\n",
  "src/scripts/runBootstrapPipeline.ts": "// src/batch/runBootstrapPipeline.ts\n//\n// \u26a0 \uac1c\ubc1c/\uc2dc\uc5f0 \ub2e8\uacc4 \uc804\uc6a9 (\ud50c\ub79c\ud2b8 \ubbf8\uc6b4\uc601 \uc0c1\ud0dc \ud55c\uc815). bootstrapAutoApproveAndPromote.ts\n//   \uc0c1\ub2e8 \uacbd\uace0 \ucc38\uc870 \u2014 \uc6b4\uc601 \uc804\ud658 \uc2dc \uc774 \uc2a4\ud06c\ub9bd\ud2b8 \ub300\uc2e0 Phase 0 \u2192 (\uc0ac\ub78c \uac80\ud1a0) \u2192\n//   promoteStagingAssetsToAssets 3\ub2e8\uacc4\ub85c \ub418\ub3cc\ub824\uc57c \ud55c\ub2e4.\n//\n// PURPOSE\n//   \"\uc9c8\ubb38 \uc5c6\uc774, mock/fallback\uc744 \uc801\uadf9 \ud65c\uc6a9\ud574 \uc778\ud504\ub77c\uc640 UI\uac00 \ub3d9\uc791\ud558\ub294 \uc0c1\ud0dc\"\ub97c\n//   \ud55c \ubc88\uc758 \uba85\ub839\uc73c\ub85c \ub9cc\ub4e0\ub2e4:\n//     1) Phase 0 Shadow Write (ISO Tank \uc2e4 CSV + \uace0\uc815\uc124\ube44 Mock/\uc2e4CSV \ud569\uc131)\n//     2) \uc0ac\ub78c \uac80\ud1a0 \uc0dd\ub7b5 \u2014 PENDING_REVIEW \uc804\ubd80 \uc790\ub3d9 \uc2b9\uc778 \ud6c4 \uc989\uc2dc \uc2b9\uaca9\n//     3) assets \ud14c\uc774\ube14\uc744 public/data/cmms_asset_snapshot.json\uc73c\ub85c export\n//        (React \ud504\ub860\ud2b8\uc5d4\ub4dc\uac00 fetch()\ub85c \ubc14\ub85c \uc18c\ube44)\n//\n// USAGE\n//   $ ISO_TANK_STATUS_LOCATION_CSV=\"public/data/NIAS - ISO TANK Status, Location.csv\" \\\n//     ISO_TANK_MASTER_DB_CSV=\"public/data/NIAS - ISO Tank Master DB.csv\" \\\n//     CMMS_SNAPSHOT_OUTPUT=\"public/data/cmms_asset_snapshot.json\" \\\n//     node dist/batch/runBootstrapPipeline.js\n//\n//   FIXED_EQUIPMENT_CSV\ub97c \uc9c0\uc815\ud558\uc9c0 \uc54a\uc73c\uba74 \uace0\uc815\uc124\ube44\ub294 \uc790\ub3d9\uc73c\ub85c Mock \ub370\uc774\ud130\ub85c \ucc44\uc6cc\uc9c4\ub2e4.\n//   \ub098\uc911\uc5d0 \uac74\uc124\uc774 \ub05d\ub098 \uc2e4\uc81c \uace0\uc815\uc124\ube44 CSV\uac00 \uc0dd\uae30\uba74, FIXED_EQUIPMENT_CSV \ud658\uacbd\ubcc0\uc218\ub9cc\n//   \ucd94\uac00\ud558\uba74 \uc774 \uc2a4\ud06c\ub9bd\ud2b8\ub97c \ud3ec\ud568\ud55c \uc5b4\ub5a4 \ucf54\ub4dc\ub3c4 \uc218\uc815\ud560 \ud544\uc694 \uc5c6\uc774 \uc2e4 \ub370\uc774\ud130\ub85c \uc804\ud658\ub41c\ub2e4.\n\nimport { existsSync } from 'node:fs';\nimport { createNodeSqliteExecutor, loadSchema } from '../adapters/db/nodeSqliteExecutor';\nimport { runShadowWriteBatch } from './shadowWriteBatch';\nimport { resolveConfiguredDataSource } from '../data/legacyDataSource';\nimport { bootstrapAutoApproveAndPromote } from './bootstrapAutoApproveAndPromote';\nimport { exportCmmsAssetSnapshot } from './exportCmmsAssetSnapshot';\n\nasync function main() {\n  const dbPath = process.env.CMMS_DB_PATH ?? './nias_cmms.db';\n  const schemaPath = process.env.CMMS_SCHEMA_PATH ?? './schema/cmms_schema.sqlite.sql';\n  const snapshotOutputPath = process.env.CMMS_SNAPSHOT_OUTPUT ?? './public/data/cmms_asset_snapshot.json';\n\n  const dbFileExisted = existsSync(dbPath);\n  const db = createNodeSqliteExecutor(dbPath);\n\n  const autoSchemaEnabled = process.env.CMMS_AUTO_SCHEMA !== 'false';\n  if (!dbFileExisted && autoSchemaEnabled) {\n    const { readFileSync } = await import('node:fs');\n    loadSchema(db.raw, readFileSync(schemaPath, 'utf8'));\n    console.log(`[bootstrap] \uc2e0\uaddc DB \uc0dd\uc131 \ubc0f \uc2a4\ud0a4\ub9c8 \uc801\uc6a9: ${dbPath}`);\n  } else {\n    console.log(`[bootstrap] \uae30\uc874 DB \uc7ac\uc0ac\uc6a9: ${dbPath}`);\n  }\n\n  console.log('\\n=== 1) Phase 0 Shadow Write ===');\n  const source = await resolveConfiguredDataSource();\n  const shadowResult = await runShadowWriteBatch(db, source);\n  console.log(\n    `\uc790\uc0b0 \ucc98\ub9ac=${shadowResult.assets.processed} (\uc2e0\uaddc ${shadowResult.assets.inserted}/\uac31\uc2e0 ${shadowResult.assets.updated}/\uac80\ud1a0\ud544\uc694 ${shadowResult.assets.needsReview})`\n  );\n  if (shadowResult.assets.errors.length > 0) {\n    console.warn(`\u26a0 \uc790\uc0b0 \ucc98\ub9ac \uc624\ub958 ${shadowResult.assets.errors.length}\uac74:`, shadowResult.assets.errors.slice(0, 5));\n  }\n\n  console.log('\\n=== 2) \uc790\ub3d9 \uc2b9\uc778 + \uc2b9\uaca9 (\uac1c\ubc1c \ub2e8\uacc4 \uc804\uc6a9 \u2014 \uc0ac\ub78c \uac80\ud1a0 \uc0dd\ub7b5) ===');\n  const bootstrapResult = bootstrapAutoApproveAndPromote(db);\n  console.log(\n    `\uc790\ub3d9 \uc2b9\uc778 ${bootstrapResult.autoApprovedCount}\uac74 \u2192 \uc2b9\uaca9 ${bootstrapResult.promoteResult.promotedCount}\uac74 \uc131\uacf5, ${bootstrapResult.promoteResult.failureCount}\uac74 \uc2e4\ud328`\n  );\n  if (bootstrapResult.promoteResult.errors.length > 0) {\n    console.warn('\u26a0 \uc2b9\uaca9 \uc624\ub958:', bootstrapResult.promoteResult.errors.slice(0, 5));\n  }\n\n  console.log('\\n=== 3) JSON \uc2a4\ub0c5\uc0f7 Export ===');\n  const snapshot = exportCmmsAssetSnapshot(db, snapshotOutputPath);\n  console.log(`${snapshot.totalCount}\uac74 export \uc644\ub8cc \u2192 ${snapshotOutputPath}`);\n  console.log(`  (mock \ub370\uc774\ud130 ${snapshot.assets.filter((a) => a.isMockData).length}\uac74 \ud3ec\ud568)`);\n\n  db.close();\n  console.log('\\n[bootstrap] \ud30c\uc774\ud504\ub77c\uc778 \uc644\ub8cc.');\n}\n\nmain().catch((err) => {\n  console.error('[bootstrap] \ud30c\uc774\ud504\ub77c\uc778 \uc2e4\ud328:', err);\n  process.exitCode = 1;\n});\n",
  "src/scripts/shadowWriteBatch.ts": "// src/scripts/shadowWriteBatch.ts\n//\n// PURPOSE\n//   Phase 0 Shadow Write \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130. staging_legacy_assets\uc5d0\ub9cc \uae30\ub85d\ud558\uace0\n//   UI\ub294 \uac74\ub4dc\ub9ac\uc9c0 \uc54a\ub294\ub2e4.\n//\n//   \u203b \uc774 \ubc84\uc804\uc740 \uc6d0\uc548(\ud5c8\uac00\uc11c/\uac00\uc2a4\uce21\uc815 \uc774\ub825\uae4c\uc9c0 \ucc98\ub9ac)\uc5d0\uc11c \ud5c8\uac00\uc11c \uad00\ub828 \ub85c\uc9c1\uc744\n//   \uc758\ub3c4\uc801\uc73c\ub85c \uc81c\uc678\ud55c \uacbd\ub7c9\ud310\uc774\ub2e4. \ud604\uc7ac \uc5f0\uacb0\ub41c \ubaa8\ub4e0 LegacyDataSource\n//   (IsoTankLegacyDataSource, FixedEquipmentLegacyDataSource,\n//   MockFixedEquipmentDataSource)\uac00 fetchPermits()\uc5d0\uc11c \ud56d\uc0c1 \ube48 \ubc30\uc5f4\uc744\n//   \ubc18\ud658\ud558\ubbc0\ub85c, \ud5c8\uac00\uc11c \ucc98\ub9ac \ucf54\ub4dc\ub294 \uc9c0\uae08 \uc2dc\uc810\uc5d0 \uc2e4\ud589\ub420 \uc77c\uc774 \uc5c6\ub2e4 \u2014\n//   e-PTW/SIMOPS \uc5f0\ub3d9\uc744 \uc2dc\uc791\ud560 \ub54c permitPersistenceAdapter.ts /\n//   gasSafetyAdapter.ts\ub97c \ud568\uaed8 \ub4e4\uc5ec\uc624\uba74\uc11c \uadf8 \ubd80\ubd84\uc744 \ub2e4\uc2dc \ucd94\uac00\ud558\uba74 \ub41c\ub2e4.\n\nimport type { SqlExecutor } from '../adapters/db/sqlExecutor';\nimport { upsertStagingAssetRow, type StagingWriteOutcome } from '../adapters/assetStagingWriter';\nimport type { LegacyDataSource } from '../data/legacyDataSource';\n\nexport interface ShadowWriteBatchResult {\n  runAt: string;\n  assets: {\n    processed: number;\n    inserted: number;\n    updated: number;\n    skippedAlreadyPromoted: number;\n    needsReview: number;\n    errors: { legacyTag: string; message: string }[];\n  };\n  permits: {\n    processed: number;\n    newlyInitialized: number;\n    alreadyExisted: number;\n    gasTestsRecorded: number;\n    errors: { permitRefNo: string; message: string }[];\n  };\n}\n\nfunction emptyResult(): ShadowWriteBatchResult {\n  return {\n    runAt: new Date().toISOString(),\n    assets: { processed: 0, inserted: 0, updated: 0, skippedAlreadyPromoted: 0, needsReview: 0, errors: [] },\n    // \ud5c8\uac00\uc11c \uce74\uc6b4\ud2b8\ub294 \ud604\uc7ac \ud56d\uc0c1 0 \u2014 \uc704 PURPOSE \ucc38\uc870. \ub9ac\ud3ec\ud2b8 \uc2a4\ud0a4\ub9c8 \ud638\ud658\uc744 \uc704\ud574 \ud544\ub4dc\ub294 \uc720\uc9c0.\n    permits: { processed: 0, newlyInitialized: 0, alreadyExisted: 0, gasTestsRecorded: 0, errors: [] },\n  };\n}\n\nexport async function runShadowWriteBatch(db: SqlExecutor, source: LegacyDataSource): Promise<ShadowWriteBatchResult> {\n  const result = emptyResult();\n\n  const assetRows = await source.fetchAssets();\n  for (const row of assetRows) {\n    result.assets.processed++;\n    try {\n      const outcome = upsertStagingAssetRow(db, row);\n      tallyAssetOutcome(result, outcome.outcome);\n      if (outcome.view.needsReview) result.assets.needsReview++;\n    } catch (err) {\n      result.assets.errors.push({ legacyTag: row.legacyTag, message: err instanceof Error ? err.message : String(err) });\n    }\n  }\n\n  // \ud5c8\uac00\uc11c: \ud604\uc7ac \ub2e8\uacc4\uc5d0\uc11c\ub294 \ucc98\ub9ac\ud558\uc9c0 \uc54a\uc74c (\uc704 PURPOSE \ucc38\uc870)\n  const permitRows = await source.fetchPermits();\n  result.permits.processed = permitRows.length; // \ud56d\uc0c1 0\uc774\uc5b4\uc57c \uc815\uc0c1\n\n  return result;\n}\n\nfunction tallyAssetOutcome(result: ShadowWriteBatchResult, outcome: StagingWriteOutcome): void {\n  if (outcome === 'INSERTED') result.assets.inserted++;\n  else if (outcome === 'UPDATED') result.assets.updated++;\n  else if (outcome === 'SKIPPED_ALREADY_PROMOTED') result.assets.skippedAlreadyPromoted++;\n}\n",
  "src/utils/CsvUtils.ts": "// src/batch/csvUtils.ts\n//\n// PURPOSE\n//   Node.js \ubc30\uce58 \ud658\uacbd\uc5d0\uc11c \uc4f8 \ucd5c\uc18c CSV \ud30c\uc11c. src/utils/csvParser.ts(React\uc6a9,\n//   \uc544\uc9c1 \ubbf8\ud655\ubcf4)\uc5d0 \uc758\uc874\ud558\uc9c0 \uc54a\uace0 \ub3c5\ub9bd\uc801\uc73c\ub85c \ub3d9\uc791\ud55c\ub2e4.\n//\n//   NIAS \uc2e4\uc81c CSV \ud30c\uc77c\ub4e4(Cert. of LNG Delivered Measurement \ub4f1)\uc5d0\n//   `\"28,720\"` \uac19\uc740 \ucc9c\ub2e8\uc704 \ucf64\ub9c8\uac00 \ud3ec\ud568\ub41c \ub530\uc634\ud45c \ud544\ub4dc\uac00 \uc788\uc5b4, \ub2e8\uc21c\n//   `line.split(',')`\ub85c\ub294 \uae68\uc9c4\ub2e4 \u2014 \ucd5c\uc18c\ud55c\uc758 RFC4180 quoting\uc744 \uc9c0\uc6d0\ud55c\ub2e4.\n\n/** \ud55c \uc904\uc744 \ud544\ub4dc \ubc30\uc5f4\ub85c \ubd84\ub9ac (\ub530\uc634\ud45c \ub0b4\ubd80\uc758 \ucf64\ub9c8\ub294 \ubb34\uc2dc) */\nfunction parseCsvLine(line: string): string[] {\n  const fields: string[] = [];\n  let current = '';\n  let inQuotes = false;\n\n  for (let i = 0; i < line.length; i++) {\n    const ch = line[i];\n    if (inQuotes) {\n      if (ch === '\"') {\n        if (line[i + 1] === '\"') {\n          current += '\"';\n          i++; // escaped quote\n        } else {\n          inQuotes = false;\n        }\n      } else {\n        current += ch;\n      }\n    } else {\n      if (ch === '\"') {\n        inQuotes = true;\n      } else if (ch === ',') {\n        fields.push(current);\n        current = '';\n      } else {\n        current += ch;\n      }\n    }\n  }\n  fields.push(current);\n  return fields;\n}\n\n/**\n * CSV \uc804\uccb4 \ud14d\uc2a4\ud2b8\ub97c \ud5e4\ub354 \uae30\uc900 \uac1d\uccb4 \ubc30\uc5f4\ub85c \ud30c\uc2f1\ud55c\ub2e4.\n * BOM(\\uFEFF) \uc81c\uac70, CRLF/LF \ubaa8\ub450 \ucc98\ub9ac, \ube48 \uc904 \uc2a4\ud0b5.\n */\nexport function parseCsv(text: string): Record<string, string>[] {\n  const cleaned = text.replace(/^\\uFEFF/, '');\n  const lines = cleaned.split(/\\r\\n|\\n/).filter((l) => l.trim().length > 0);\n  if (lines.length === 0) return [];\n\n  const headers = parseCsvLine(lines[0]).map((h) => h.trim());\n  const rows: Record<string, string>[] = [];\n\n  for (let i = 1; i < lines.length; i++) {\n    const values = parseCsvLine(lines[i]);\n    const row: Record<string, string> = {};\n    headers.forEach((h, idx) => {\n      row[h] = (values[idx] ?? '').trim();\n    });\n    rows.push(row);\n  }\n  return rows;\n}\n\n/** \uc22b\uc790 \ud30c\uc2f1 \ud5ec\ud37c \u2014 \ucc9c\ub2e8\uc704 \ucf64\ub9c8 \uc81c\uac70 \ud6c4 \ud30c\uc2f1, \uc2e4\ud328 \uc2dc undefined */\nexport function parseNumericField(raw: string | undefined): number | undefined {\n  if (!raw || raw.trim() === '') return undefined;\n  const cleaned = raw.replace(/,/g, '').trim();\n  const n = Number(cleaned);\n  return Number.isFinite(n) ? n : undefined;\n}\n",
};

