let allGood = true;
for (const [dest, content] of Object.entries(files)) {
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, content, 'utf8');
  const actualLines = content.split('\n').length - 1; // wc -l 방식과 동일 (trailing newline 보정)
  const fname = path.basename(dest);
  const exp = expected[fname];
  if (exp && actualLines !== exp) {
    console.log(`MISMATCH: ${fname.padEnd(40)} actual=${actualLines} expected=${exp}`);
    allGood = false;
  } else {
    console.log(`OK:       ${fname.padEnd(40)} ${actualLines} lines`);
  }
}

